    { key: 'הו"ק', idField: 'pcfPaymentPageIdSO', urlField: 'pcfPaymentUrlSO' },
  ];

  // קטגוריית מוצר מתוך הקטלוג (100=בוסט · 101=פרימיום/ליווי · 102=המשך)
  function catOfProduct(pid) {
    const id = S(pid).toUpperCase();
    if (!id) return '';
    const pr = products.find((x) => S(x.productid).toUpperCase() === id);
    return pr ? S(pr.categorycode) : '';
  }

  function matchProduct() {
    if (!products.length) return { product: null, how: 'אין קטלוג', route: '', matchedId: '' };
    const alias = cfg.PRODUCT_ID_ALIASES || {};
    const cand = [S(ev.growProductId), S(ev.growProcessId)].filter(Boolean);
    const aliased = cand.map((c) => S(alias[c])).filter(Boolean);
    const all = cand.concat(aliased);

    for (let i = 0; i < PAY_ROUTES.length; i++) {
      const r = PAY_ROUTES[i];
      const byId = products.find((pr) => S(pr[r.idField]) && all.indexOf(S(pr[r.idField])) !== -1);
      if (byId) {
        const mid = S(byId[r.idField]);
        return {
          product: byId, route: r.key, matchedId: mid,
          how: aliased.length && cand.indexOf(mid) === -1 ? 'alias' : 'pageid',
        };
      }
    }

    let hit = products.find((pr) => S(pr.productid) && all.indexOf(S(pr.productid)) !== -1);
    if (hit) return { product: hit, how: 'productid', route: '', matchedId: S(hit.productid) };

    for (let j = 0; j < PAY_ROUTES.length; j++) {
      const r2 = PAY_ROUTES[j];
      const byUrl = products.find((pr) => { const id = urlProcessId(pr[r2.urlField]); return id && all.indexOf(id) !== -1; });
      if (byUrl) return { product: byUrl, how: 'קישור תשלום', route: r2.key, matchedId: urlProcessId(byUrl[r2.urlField]) };
    }

    // מיפוי ידני של שמות מהמערכת הישנה (PRODUCT_NAME_ALIASES).
    // קודם לניקוד הטוקנים — זהו מקור ודאי שנמסר ע"י המשתמש, ולכן חזק יותר
    // מהיוריסטיקה. ההשוואה על מחרוזת מלאה מנורמלת בלבד.
    const nameAlias = cfg.PRODUCT_NAME_ALIASES || {};
    const rawNames = [ev.growProductName, ev.descriptionText];
    for (let k = 0; k < rawNames.length; k++) {
      const key = normName(rawNames[k]);
      if (!key) continue;
      const aliasPid = S(nameAlias[key]);
      if (!aliasPid) continue;
      const byAliasName = products.find(
        (pr) => S(pr.productid).toUpperCase() === aliasPid.toUpperCase());
      if (byAliasName) {
        return { product: byAliasName, how: 'alias שם', route: '', matchedId: '' };
      }
    }

    // נפילה אחרונה — התאמה לפי שם, רק אם יש מנצח יחיד ומובהק.
    // כשאין productData כלל (הפורמט הישיר של גרואו) משתמשים בתיאור העסקה.
    const gTok = tokens(ev.growProductName || ev.descriptionText);
    if (gTok.length) {
      const scored = products.map((pr) => ({
        pr, score: tokens(pr.name).filter((w) => gTok.indexOf(w) !== -1).length,
      })).filter((x) => x.score > 0).sort((a, b) => b.score - a.score);
      if (scored.length && (scored.length === 1 || scored[0].score > scored[1].score)) {
        return { product: scored[0].pr, how: 'שם', route: '', matchedId: '' };
      }
    }
    return { product: null, how: '', route: '', matchedId: '' };
  }

  const pm = matchProduct();
  let product = pm.product;
  let productId = product ? S(product.productid) : '';

  // וובהוקים בפורמט legacy (הו"ק, חיוב חוזר) לא נושאים productData כלל.
  // במקרה כזה המוצר נגזר מתהליך המכירה שמקושר לרשומת התשלום המקורית.
  const byId = (pid) => products.find((x) => S(x.productid).toUpperCase() === S(pid).toUpperCase()) || null;
  if (!product && txPayment && S(txPayment.pcfSale)) {
    const srcSale = sales.find((x) => S(x.opportunityid).toUpperCase() === S(txPayment.pcfSale).toUpperCase());
    if (srcSale && S(srcSale.pcfProduct)) {
      const viaSale = byId(srcSale.pcfProduct);
      if (viaSale) { product = viaSale; productId = S(viaSale.productid); pm.how = 'מתהליך המכירה של התשלום המקורי'; }
    }
  }
  let productName = product ? S(product.name) : (ev.growProductName || 'מוצר לא מזוהה');
  if (product && pm.how === 'alias') {
    decisions.push(`המוצר הותאם דרך טבלת המזהים הנוספים (${ev.growProductId || ev.growProcessId} → ${S(pm.matchedId)}).`);
  }
  if (product && pm.how === 'alias שם') {
    decisions.push(`המוצר "${S(product.name)}" הותאם לפי טבלת שמות המערכת הישנה ("${normName(ev.growProductName || ev.descriptionText)}").`);
  }
  if (product && pm.route) {
    decisions.push(`המוצר "${S(product.name)}" זוהה במסלול התשלום "${pm.route}" (${pm.how === 'קישור תשלום' ? 'לפי קישור התשלום' : 'לפי מזהה GROW'}).`);
  }
  if (product && pm.how === 'שם') {
    warnings.push(`המוצר "${productName}" הותאם לפי טקסט ("${ev.growProductName || ev.descriptionText}") ולא לפי מזהה — מומלץ להשלים את מזהה GROW ${ev.growProductId || ev.growProcessId} בשדה "מזהה מוצר GROW - אשראי רגיל" או "מזהה מוצר GROW - הו״ק" לפי מסלול הרכישה.`);
  }
  if (product && pm.how === 'מתהליך המכירה של התשלום המקורי') {
    decisions.push('המוצר נגזר מתהליך המכירה של רשומת התשלום המקורית (הוובהוק לא נשא נתוני מוצר).');
  }
  if ((ev.growProductId || ev.growProcessId) && !product) {
    warnings.push(`מזהי המוצר מגרואו (product_id=${ev.growProductId || '—'}, payment_link=${ev.growProcessId || '—'}) לא נמצאו באף מוצר בפיירברי — לא בשדות האשראי הרגיל ולא בשדות ההו״ק. שם המוצר נלקח מגרואו כפי שהוא.`);
  }

  // ---------- 3א. בחירת תהליך המכירה — לפי המוצר שנרכש ----------
  // החלטת אליאל 19/08/2026: "לפי מוצר בלבד — אם נרכש בוסט, זה רק תהליך מכירה של בוסט."
  // אומת חי: השדה pcfProduct מאוכלס ב-30/30 תהליכי המכירה האחרונים.
  function selectSale() {
    // 🔴 כשקיימת רשומת תשלום שהאירוע הזה משתייך אליה (חשבונית, חיוב חוזר,
    //    מסירה חוזרת) — המכירה נלקחת *ממנה בלבד*. אסור לבחור מכירה מחדש:
    //    זה שייך את המסמך לעסקה אחרת של אותה לקוחה. (נתפס בהרצה חיה 19/08.)
    if (txPayment) {
      const linked = S(txPayment.pcfSale);
      if (!linked) return { sale: null, why: 'רשומת התשלום המקורית אינה משויכת לתהליך מכירה' };
      const full = sales.find((x) => S(x.opportunityid).toUpperCase() === linked.toUpperCase());
      return { sale: full || { opportunityid: linked, ownerid: S(txPayment.ownerid) },
               why: 'נלקח מרשומת התשלום המקורית' };
    }
    // 🔴 15/09/2026 — עוזרים לבחירה: אותה חיפוש בדיוק, פעם על הפתוחים ופעם
    //    על *כל* העסקאות (כולל סגורות). ראה ההערה על CLOSED בהמשך.
    function pickExact(pool) {
      if (!productId) return null;
      const hit = pool.filter((x) => S(x.pcfProduct).toUpperCase() === productId.toUpperCase());
      return hit.length ? hit[0] : null;
    }
    function pickCategory(pool) {
      if (!cfg.SALE_MATCH_BY_CATEGORY || !productCategory) return null;
      const hit = pool.filter((x) => {
        const c = catOfProduct(x.pcfProduct);
        return c && c === productCategory;
      });
      return hit.length ? hit[0] : null;
    }

    if (!cfg.SALE_MATCH_BY_PRODUCT || !productId) {
      if (openSales.length) return { sale: openSales[0], why: 'הפתוח החדש ביותר' };
    }

    // ── 1. עסקה פתוחה של אותו מוצר בדיוק ──
    const byProduct = openSales.length ? pickExact(openSales) : null;
    if (byProduct) return { sale: byProduct, why: 'התאמה למוצר שנרכש' };

    // 🔴 15/09/2026 — התאמה לפי **קטגוריה**. תהליך מכירה מייצג קטגוריה
    //    (בוסט / פרימיום / המשך) ולא מוצר בודד, ולכן תשלום על מוצר אחר
    //    מאותה קטגוריה מצטרף לתהליך הפתוח הקיים והמוצר שלו מתעדכן.
    const byCatOpen = openSales.length ? pickCategory(openSales) : null;
    if (byCatOpen) {
      return { sale: byCatOpen, updateProduct: true,
        why: `אין תהליך מכירה פתוח של "${productName}", אבל יש פתוח מאותה קטגוריה — התשלום משויך אליו והמוצר שבו מתעדכן` };
    }

    // ── 3. עסקה **סגורה** של אותה קטגוריה ──
    // 🔴 15/09/2026, הכרעת אליאל: תהליך המכירה מייצג קטגוריה (בוסט/פרימיום/
    //    המשך) ויש בדיוק אחד כזה ללקוחה. חיוב הו"ק חוזר או רכישה נוספת באותה
    //    קטגוריה מגיעים אחרי שהעסקה כבר נסגרה בהצלחה — ולכן החיפוש רק בין
    //    הפתוחות פתח עסקה חדשה בכל פעם וייצר בדיוק את הכפילויות שאיחדנו.
    //    לכן: אם אין פתוחה מתאימה — מחפשים בכל העסקאות, כולל הסגורות.
    //    הסטטוס של העסקה הסגורה **לא משתנה** — היא נשארת "נסגרה בהצלחה".
    if (cfg.SALE_MATCH_INCLUDE_CLOSED !== false) {
      const exactAny = pickExact(sales);
      if (exactAny) {
        return { sale: exactAny, attachedToClosed: true,
          why: `אין תהליך מכירה פתוח, אבל קיים תהליך של "${productName}" — התשלום משויך אליו ולא נפתח חדש` };
      }
      const catAny = pickCategory(sales);
      if (catAny) {
        return { sale: catAny, updateProduct: true, attachedToClosed: true,
          why: `אין תהליך מכירה פתוח, אבל קיים תהליך מאותה קטגוריה — התשלום משויך אליו והמוצר שבו מתעדכן` };
      }
    }

    // ── 3ב. ליד פתוח **בלי מוצר** ──
    // 🔴 16/09/2026 — נתפס אצל יהודית סואייה: להגירה יש 14,764 לידים
    //    ("עסקה - X | ליד") בלי מוצר כלל. הם חסרי קטגוריה, ולכן כל החיפושים
    //    לפי מוצר/קטגוריה דילגו עליהם ונפתחה עסקה חדשה — בדיוק מול הליד
    //    הפתוח שהמשתמש מצפה שהתשלום ייתלה עליו.
    //    ליד הוא שלב טרום-רכישה; רכישה הופכת אותו לעסקה ומעדכנת את המוצר.
    //    מכוון שהוא בא **אחרי** חיפוש הסגורות — לקוחה עם עסקה סגורה מאותה
    //    קטגוריה לא תייצר עסקה שנייה בקטגוריה הזו דרך ליד ישן.
    if (cfg.SALE_MATCH_EMPTY_LEAD !== false && productId) {
      const emptyLead = openSales.filter((x) => !S(x.pcfProduct));
      if (emptyLead.length) {
        return { sale: emptyLead[0], updateProduct: true, attachedToLead: true,
          why: `נמצא תהליך מכירה פתוח בלי מוצר (ליד) — התשלום משויך אליו והמוצר שלו נקבע ל"${productName}"` };
      }
    }

    // ── 4. אין שום התאמה — עסקה חדשה ──
    return { sale: null, createNew: true, why: sales.length
      ? `אין ללקוחה תהליך מכירה מהקטגוריה של "${productName}" — ייפתח תהליך מכירה חדש`
      : 'אין ללקוחה שום תהליך מכירה — ייפתח תהליך מכירה חדש' };
  }

  const productCategory = catOfProduct(productId);
  const sel = selectSale();
  let sale = sel.sale;
  // 🔴 אם אין תהליך פתוח ויש לחשבון — פותחים תהליך מכירה חדש לחלוטין (13/09/2026).
  // אין כאן סגירה/מחזור/קבוצה — זה תפקידם של WF-22/23, בדיוק כמו בכל רכישה תקינה רגילה.
  if (sel.createNew && accountFound) {
    const newSaleRef = add({
      ref: 'newSale', kind: 'create', object: '4', label: 'יצירת תהליך מכירה חדש (4)',
      body: Object.assign(
        { name: `העסקה של ${accountName || ev.fullName || 'לקוחה לא מזוהה'}`,
          accountid, ownerid: accountOwner || defaultRep || '', statuscode: 2, pcfCreatedByPersonOrSystem: 2 },
        productId ? { pcfProduct: productId } : {},
        // 🔴 16/09/2026 — פיירברי לא מעתיקה טלפון/אימייל מהלקוחה לעסקה. כותבים במפורש.
        (S(ev.phone) || (account && S(account.telephone1))) ? { pcfTelephone1: S(ev.phone) || S(account.telephone1) } : {},
        (S(ev.email) || accountEmail) ? { pcfemailaddress: S(ev.email) || accountEmail } : {}
      ),
    });
    sale = { opportunityid: newSaleRef, ownerid: accountOwner || defaultRep || '' };
  }
  // 🔴 שויכנו לתהליך פתוח מאותה קטגוריה אבל של מוצר אחר — מעדכנים בו את המוצר
  //    לפי מה שנסלק בפועל. (הכרעת אליאל 15/09/2026)
  if (sel.attachedToLead && sale) {
    decisions.push(`התשלום שויך לליד הפתוח שכבר היה ללקוחה (${S(sale.name) || S(sale.opportunityid)}) — הליד הפך לעסקה במקום שתיפתח כפילות.`);
  }
  if (sel.attachedToClosed && sale) {
    decisions.push(`התשלום שויך לתהליך מכירה קיים שכבר נסגר (${S(sale.name) || S(sale.opportunityid)}) — לפי הכלל שתהליך מכירה אחד לכל קטגוריה. הסטטוס שלו לא שונה.`);
  }
  if (sel.updateProduct && sale && productId
      && S(sale.pcfProduct).toUpperCase() !== S(productId).toUpperCase()) {
    add({ ref: 'saleProduct', kind: 'update', object: '4',
      recordId: S(sale.opportunityid),
      label: 'עדכון המוצר בתהליך המכירה לפי מה שנסלק',
      body: { pcfProduct: productId } });
    decisions.push(`המוצר בתהליך המכירה עודכן ל"${productName}" לפי התשלום שהתקבל (היה: ${S(sale.pcfProductname) || '—'}).`);
  }
  // 🔴 24/09/2026 (סער) — תהליך מכירה קיים שנבחר בלי נציג משויך ⇒ שיוך לנציג הדיפולט מההגדרות.
  //    תהליך שיש לו נציג — לא נוגעים בו.
  if (sale && !S(sale.ownerid) && defaultRep) {
    add({ ref: 'saleOwner', kind: 'update', object: '4',
      recordId: S(sale.opportunityid),
      label: 'שיוך נציג מכירות לתהליך לפי ההגדרות',
      body: { ownerid: defaultRep } });
    sale.ownerid = defaultRep;
    decisions.push('לתהליך המכירה לא היה נציג משויך — שויך לנציג הדיפולט מאובייקט ההגדרות.');
  }
  // אם עדיין אין מוצר — לגזור אותו מתהליך המכירה שנבחר (למשל הקמת הו"ק בפורמט legacy)
  if (!product && sale && S(sale.pcfProduct)) {
    const viaSel = byId(sale.pcfProduct);
    if (viaSel) {
      product = viaSel; productId = S(viaSel.productid); productName = S(viaSel.name);
      decisions.push('המוצר נגזר מתהליך המכירה שנבחר (הוובהוק לא נשא נתוני מוצר).');
      // 🔴 אם תיאור החיוב מדבר על מוצר אחר — לא לבלוע בשקט.
      const descTok = tokens(ev.growProductName || ev.descriptionText);
      if (descTok.length) {
        const selTok = tokens(productName);
        const overlap = descTok.filter((w) => selTok.indexOf(w) !== -1).length;
        if (overlap < 2) {
          warnings.push(`תיאור החיוב ("${ev.growProductName || ev.descriptionText}") אינו תואם את המוצר שנבחר מתהליך המכירה ("${productName}") — יש לאמת ידנית איזה מוצר נרכש.`);
        }
      }
    }
  }
  // 🔴 15/09/2026 — עד היום, כשלא היה **שום** מזהה מוצר בוובהוק (הפורמט הישיר
  //    של גרואו) וגם ההתאמה לפי שם נכשלה, המערכת שתקה לגמרי: לא אזהרה ולא משימה.
  //    התוצאה — "מוצר לא מזוהה" נכתב לרשומות, WF-22 לא יכול לסווג בלי קטגוריה,
  //    ולכן **שום תהליך מקצועי לא רץ**: אין ליווי, אין קבוצה, אין תפריט, אין וולקאם.
  //    נתפס חי אצל חן בוסקילה (ריצה 254620): תיאור התשלום היה
  //    "ליווי אונליין מנטורית אישית", שלא תואם לאף שם מוצר בקטלוג.
  //    מעכשיו — כישלון זיהוי מוצר ברכישה **תמיד** מדווח בקול.
  // מתריעים רק כשהזיהוי הכושל **באמת עולה במשהו** — כלומר ברכישה חדשה או
  // בהקמת הוראת קבע, שבהן אמורה לרוץ שרשרת הקמת המוצר. חיוב חודשי של הוראה
  // ותיקה לא מקים שום דבר, ולכן משימה עליו היא רעש בלבד (21 מתוך 250 ריצות
  // אחרונות היו כאלה — כולן חיובי המשך של לקוחות המשך ותיקות).
  const isPurchaseEvent = S(ev.eventType) === 'PAYMENT'
    || ev.isSetupSource === true || ev.isBackOfficeSource === true;
  const productUnidentified = !product && ev.isSuccess === true && isPurchaseEvent;
  // 🔴 מחושב **אחרי** כל נפילות הזיהוי, כולל הגזירה מתהליך המכירה — אחרת
  //    היינו פותחים משימה גם כשהמוצר בסוף כן זוהה.

  const saleid = sale ? S(sale.opportunityid) : '';
  const saleFound = !!saleid;
  if (saleFound) decisions.push(`תהליך מכירה נבחר — ${sel.why}.`);
  else warnings.push(`לא שויך תהליך מכירה: ${sel.why}. הרשומות ייווצרו בלי שיוך ותיפתח משימה לטיפול ידני.`);
  const ownerid = (sale && S(sale.ownerid)) || accountOwner || '';

  // ---------- 4. שמות ידידותיים ----------
  const custLabel = accountName || ev.fullName || 'לקוחה לא מזוהה';
  const money = (n) => `${round2(n)} ₪`;

  // ---------- 5. עזרים לבניית גופי רשומות ----------
  function lookupOrOmit(obj, key, val) { if (S(val)) obj[key] = S(val); return obj; }

  function buildPaymentBody(opts) {
    const b = {
      name: cut(opts.name, 190),
      // 1 = בתהליך פירעון · 2 = נפרע בהצלחה (רכישה בתשלום אחד שנפרע במלואו)
      pcfStatus: opts.status || 1,
      pcfstatusupdatedate: ev.nowISO,
      pcfID: S(opts.chargeId),
      // 🔴 08/09/2026 — "אמצעי תשלום" חייב לתאר אמצעי תשלום אמיתי בלבד (אשראי/מזומן/...)
      // ולעולם לא "הוראת קבע". מעכשיו האם זו הוראת קבע נכתב אך ורק ב-pcfPaymentCategory.
      pcfPaymentType: opts.paymentType,
      pcfNeedToPay: opts.net,
      pcfNeedToPayIncludingVat: opts.gross,
      pcftaxincludecode: 1,                           // כולל מע"מ = כן
      pcfFirstPaymentDate: opts.firstPaymentDate,
      pcfLastPaymentDate: opts.lastPaymentDate || opts.firstPaymentDate,
      pcfNextPaymentDate: opts.nextPaymentDate || null,
      pcfCreatedByPersonOrSystem: 2,                  // מערכת
      pcfExternalSoftwareID1: opts.idemKey,
      // מזהה העסקה בפורמט ה-legacy של גרואו — זהו המפתח שוובהוק החשבונית מגיע איתו.
      pcfExternalSoftwareID2: S(ev.transactionCode) || 'GROW',
    };
    // קופון — נכתב רק כשיש הנחה בפועל
    if (ev.couponDiscount > 0) {
      b.pcfCouponDiscount = ev.couponDiscount;
      b.pcfCouponCode = cut(ev.couponCode || 'הנחה ללא קוד', 190);
    }
    // 🔴 מספר תשלומים 0 + סכום = קריסה בפיירברי (חלוקה באפס בשדה המחושב).
    // null ⇒ השדה לא נשלח כלל.
    if (opts.numberOfPayments !== null && opts.numberOfPayments !== undefined) {
      b.pcfNumberOfPayments = opts.numberOfPayments;
    }
    // 🔴 08/09/2026 — "סוג תשלום" (רגיל/תשלומים/הוראת קבע) — שדה חדש על 1039,
    //    נפרד לגמרי מ"אמצעי תשלום". נכתב תמיד כשמועבר מה-caller.
    if (opts.paymentCategory !== null && opts.paymentCategory !== undefined) {
      b.pcfPaymentCategory = opts.paymentCategory;
    }
    lookupOrOmit(b, 'pcfAccountid', accountid);
    lookupOrOmit(b, 'pcfSale', saleid);
    lookupOrOmit(b, 'ownerid', ownerid);
    // 🔴 "מוצר מקושר" — נכתב בכל סוגי התשלום (רגיל / פריסה / הוראת קבע),
    //    אך **רק** כשהמוצר זוהה בוודאות. שדה לא חובה — עדיף ריק מאשר שגוי.
    lookupOrOmit(b, 'pcfrelatedproduct', productId);
    return b;
  }

  function buildDocBody(opts) {
    const b = {
      name: cut(opts.name, 190),
      pcfReference: S(ev.asmachta),
      pcfPaymetStatus: opts.status,
      pcfsStatusUpdateTime: ev.nowISO,
      pcfPaymentType: opts.paymentType,
      pcftaxincludecode: 1,
      pcfPayed: opts.net,
      pcfPayedIncludingVAT: opts.gross,
      pcfCreatedByPersonOrSystem: 2,
      pcfExternalSoftwareID1: opts.idemKey,
      pcfExternalSoftwareID2: S(ev.transactionCode) || 'GROW',
    };
    // 🔴 08/09/2026 — "סוג תשלום" (pcfPaymentCategory) נכתב רק על רשומת התשלום
    //    (1039), לא כאן. תיעוד תשלום (1018) הוא נגזרת: מגיע דרך pcfPaymentCollection
    //    לרשומת האב, ואין טעם לשכפל את הסיווג על כל תיעוד — כפילות מיותרת (אליאל, 08/09).
    // מספר מסמך מגיע רק מוובהוק החשבונית הנפרד — לא ממולא כאן.
    if (S(ev.invoiceNumber)) b.pcfInvoiceNumber1 = S(ev.invoiceNumber);
    // "בתשלום ששולם — תאריך התשלום. בעתידיים — טרם למלא." (אפיון אליאל)
    // 🔴 אומת חי 19/08: השמטת השדה גורמת לפיירברי למלא אותו בתאריך היצירה.
    // חייבים לשלוח null מפורש כדי שיישאר ריק.
    b.pcfPaymentDate = opts.paymentDate || null;
    lookupOrOmit(b, 'pcfAccountid', accountid);
    lookupOrOmit(b, 'pcfSale', saleid);
    lookupOrOmit(b, 'ownerid', ownerid);
    if (opts.paymentRef) b.pcfPaymentCollection = opts.paymentRef;
    return b;
  }

  function noteOp(ref, text) {
    if (!saleid) { warnings.push('אין תהליך מכירה — ההערה לא צורפה אליו.'); return null; }
    return add({
      ref, kind: 'create', object: 'note', label: 'הערה על תהליך המכירה',
      body: { notetext: text, objectid: saleid, objecttypecode: 4 },
    });
  }
  // הערה על רשומה שנוצרת באותה ריצה (מזהה כ-@ref) או על רשומה קיימת (GUID)
  // 🔴 "מספר תשלומים" בהוראת קבע: הערך נכתב בפעולת **עדכון** נפרדת ולא בגוף
  //    היצירה, כי POST עם 0 + סכום מפיל את פיירברי (חלוקה באפס בשדה המחושב)
  //    ואילו PUT עם אותו ערך עובר תקין. אומת חי 19/08.
  function soCountOnCreate() {
    return cfg.STANDING_ORDER_COUNT_VIA_UPDATE ? null : cfg.STANDING_ORDER_PAYMENTS_COUNT;
  }
  function addSoCountUpdate(payRef) {
    const cnt = cfg.STANDING_ORDER_PAYMENTS_COUNT;
    if (!cfg.STANDING_ORDER_COUNT_VIA_UPDATE) return;
    if (cnt === null || cnt === undefined) return;
    add({ ref: 'soCount', kind: 'update', object: '1039', recordIdRef: payRef,
      label: 'השלמת "מספר תשלומים" בהוראת הקבע', body: { pcfNumberOfPayments: cnt } });
  }

  function noteOn(ref, targetRef, objectTypeCode, label, text) {
    return add({
      ref, kind: 'create', object: 'note', label,
      body: { notetext: text, objectid: targetRef, objecttypecode: objectTypeCode },
    });
  }

  function taskOp(ref, subject, description) {
    const b = {
      subject: cut(subject, 190),
      description: cut(description, 4000),
      statuscode: cfg.DEFAULT_TASK_STATUS,
      prioritycode: cfg.DEFAULT_TASK_PRIORITY,
      tasktypecode: cfg.DEFAULT_TASK_TYPE,
      scheduledend: ev.todayISO,
      pcfCreatedByPersonOrSystem: 2,
      pcfExternalSoftwareID1: `${ev.idemKeyBase}-TASK-${ref}`,
    };
    lookupOrOmit(b, 'pcfSale', saleid);
    lookupOrOmit(b, 'pcfClient', accountid);
    lookupOrOmit(b, 'ownerid', ownerid);
    return add({ ref, kind: 'create', object: '10', label: 'משימה לנציג', body: b });
  }

  const couponLine = ev.couponDiscount > 0
    ? `<br>קופון: <b>${ev.couponCode || 'ללא קוד'}</b> · הנחה: <b>${money(ev.couponDiscount)}</b>` +
      `${ev.listedTotal ? ` (מחיר מחירון ${money(ev.listedTotal)})` : ''}` +
      `<br><i>מקור נתוני הקופון: ${ev.couponSource}</i>`
    : '';
  const execLink = ev.executionUrl
    ? `<a href="${ev.executionUrl}">${ev.executionUrl}</a>`
    : '(אין קישור execution)';

  // ---------- 6. אידמפוטנטיות ----------
  // אם כבר קיימת רשומת 1039 עם אותו מפתח — זו מסירה חוזרת של גרואו. לא יוצרים כלום.
  const dup = txPayments.find((p) => S(p.pcfExternalSoftwareID1) === ev.idemKeyBase);
  // 🔴 מסמך שכבר נוצר מאותה חשבונית — גרואו מוסר את הוובהוק יותר מפעם אחת
  // ובלי הבדיקה הזו נוצרות רשומות מסמך כפולות. (נתפס חי 19/08.)
  const dupInvoice = recentDocs.find((p) => S(p.pcfExternalSoftwareID1) === ev.idemKeyBase);
  const dupDoc = docs.find((p) => S(p.pcfExternalSoftwareID1).indexOf(ev.idemKeyBase) === 0);
  // 🔴 חיוב מתוך הוראת קבע אינו יוצר רשומת 1039 חדשה — רק תיעוד תשלום.
  // לכן מסירה חוזרת שלו לא נתפסת ע"י בדיקת ה-1039 ותייצר תיעוד כפול.
  // הבדיקה כאן היא על התאמה **מדויקת** של המפתח: תיעודי פריסה נושאים סיומת -1/-2/…
  const dupPayDoc = docs.find((p) => S(p.pcfExternalSoftwareID1) === ev.idemKeyBase);

  // 🔴 אם גרואו ישתמש באותה אסמכתא גם בחיובי ההמשך של פריסה, בדיקת הכפילות
  // הייתה בולעת אותם בשקט. לכן: אסמכתא מוכרת + סכום שתואם חיוב בודד +
  // קיים תיעוד שממתין לפירעון ⇒ זה חיוב המשך, לא מסירה חוזרת.
  let dupIsInstallment = false;
  if (dup && ev.eventType !== 'INVOICE' && ev.isSuccess) {
    const total = parseFloat(dup.pcfNeedToPayIncludingVat) || 0;
    const cnt = parseInt(dup.pcfNumberOfPayments, 10) || 1;
    const per = cnt > 0 ? round2(total / cnt) : total;
    const pend = docs.filter((x) => S(x.pcfPaymentCollection) === S(dup.customobject1039id))
                     .filter((x) => pickNum(x.pcfPaymetStatus, DS_LABELS) === 3);
    if (cnt > 1 && pend.length > 0 && Math.abs(per - (ev.grossTotal || 0)) <= 1 &&
        (ev.grossTotal || 0) < total - 0.01) {
      dupIsInstallment = true;
      decisions.push('אותה אסמכתא, אך הסכום תואם חיוב בודד מתוך הפריסה — מטופל כחיוב המשך ולא כמסירה חוזרת.');
    }
  }

  if (!dupIsInstallment && (dup || dupPayDoc || (ev.eventType === 'INVOICE' && (dupInvoice || dupDoc)))) {
    // 🔴 אותה עסקה מגיעה מגרואו פעמיים, בשני פורמטים, כשלכל אחד מזהה אחר:
    //    paymentLinks נושא transactionId ואת המוצר; legacy נושא transactionCode
    //    (וזה המזהה שוובהוק החשבונית יגיע איתו).
    //    לכן המסירה השנייה לא נזרקת — היא **משלימה** את מה שחסר ברשומה הקיימת.
    let enriched = [];
    if (dup) {
      const upd = {};
      const curCode = S(dup.pcfExternalSoftwareID2);
      if (S(ev.transactionCode) && curCode !== S(ev.transactionCode) && (!curCode || curCode === 'GROW')) {
        upd.pcfExternalSoftwareID2 = S(ev.transactionCode);
        enriched.push('מזהה עסקה legacy (לשיוך החשבונית)');
      }
      if (S(ev.transactionId) && !S(dup.pcfID)) {
        upd.pcfID = S(ev.transactionId);
        enriched.push('מזהה חיוב');
      }
      if (Object.keys(upd).length) {
        add({ ref: 'enrich', kind: 'update', object: '1039',
          recordId: S(dup.customobject1039id),
          label: 'השלמת מזהי GROW ברשומת התשלום הקיימת', body: upd });
      }
    }
    decisions.push('DUPLICATE');
    return [{ json: {
      ...ev, branch: 'DUPLICATE', ops, warnings, decisions,
      summary: enriched.length
        ? `מסירה חוזרת של אותה עסקה — לא נוצרה רשומה חדשה. הושלמו ברשומה הקיימת: ${enriched.join(', ')}.`
        : (dupInvoice
            ? `החשבונית ${ev.invoiceNumber} כבר נקלטה בעבר (מסמך קיים) — לא נוצרה רשומה כפולה.`
            : (!dup && dupPayDoc
                ? 'החיוב הזה כבר נקלט בעבר (קיים תיעוד תשלום עם אותה אסמכתא) — לא נוצר תיעוד כפול.'
                : 'הוובהוק כבר עובד בעבר (אותה אסמכתא) — לא נוצרה שום רשומה.')),
      accountid, accountName: custLabel, accountEmail, saleid, productName, productId, ownerid,
    } }];
  }

  // ---------- 7. ניתוב ----------
  let branch = dupIsInstallment ? 'INSTALLMENT_CHARGE' : ev.eventType;

  // רשומת התשלום המקורית עבור חיוב המשך
  // 🔴 מספר התשלום בתוך הפריסה מקודד במזהה החיצוני של התיעוד: GROW-{אסמכתא}-{N}.
  //    זהו ה-ID של התשלום הבודד, והוא המפתח היחיד לשיוך חיוב לתיעוד.
  function installmentIndexOf(x) {
    const m = /-(\d+)$/.exec(S(x.pcfExternalSoftwareID1));
    return m ? parseInt(m[1], 10) : null;
  }

  function docsOfPayment(paymentId) {
    return docs.filter((x) => S(x.pcfPaymentCollection) === S(paymentId));
  }

  function pendingDocsFor(paymentId) {
    // מיון דטרמיניסטי: קודם לפי מספר התשלום שבמזהה, ורק בהיעדרו לפי תאריך החיוב.
    // (createdon אינו מבחין — כל התיעודים נוצרים באותה שנייה. נתפס חי 19/08.)
    const idx = (x) => { const i = installmentIndexOf(x); return i === null ? 999999 : i; };
    const key = (x) => S(x.pcfPaymentDate) || S(x.createdon) || '';
    return docsOfPayment(paymentId)
      .filter((x) => pickNum(x.pcfPaymetStatus, DS_LABELS) === 3)
      .sort((a, b) => (idx(a) - idx(b)) || key(a).localeCompare(key(b)));
  }

  // 🔴 בחירת התיעוד שייפרע — **לפי מזהה בלבד**.
  //    התשלום הבא בתור = כמות התיעודים שכבר נפרעו + 1, ומחפשים את התיעוד
  //    שהמזהה שלו מסתיים במספר הזה. אין בחירה לפי סכום ואין "הראשון ברשימה".
  function selectInstallmentTarget(srcId) {
    const all = docsOfPayment(srcId);
    const pend = pendingDocsFor(srcId);
    if (!pend.length) return { target: null, why: 'אין תיעוד תשלום שממתין לפירעון תחת התשלום המקור' };
    const paid = all.filter((x) => pickNum(x.pcfPaymetStatus, DS_LABELS) === 1).length;
    const expectIdx = paid + 1;
    const byId = pend.find((x) => installmentIndexOf(x) === expectIdx);
    if (byId) return { target: byId, why: `שויך לפי מזהה התיעוד — תשלום ${expectIdx} בפריסה` };
    const indexed = pend.filter((x) => installmentIndexOf(x) !== null);
    if (indexed.length) {
      return { target: indexed[0],
        why: `שויך לפי מזהה התיעוד — התשלום הממתין הנמוך ביותר (${installmentIndexOf(indexed[0])})`,
        note: `התשלום המצופה היה ${expectIdx} ולא נמצא ממתין בשם הזה.` };
    }
    // 🔴 כלל קשיח, בלי מתג: אין מזהה תשלום ⇒ לא נוגעים. גם כשיש מועמד יחיד.
    //    "המועמד היחיד" הוא בדיוק ההיגיון שהצמיד חשבונית של לקוחה אחת
    //    לתשלום של לקוחה אחרת ב-20/08. הוא נפסל בכל המערכת.
    return { target: null, blocked: true,
      why: pend.length > 1
        ? 'יש יותר מתיעוד ממתין אחד ולאף אחד אין מזהה תשלום — אסור לנחש'
        : 'לתיעוד הממתין אין מזהה תשלום — שיוך אפשרי רק לפי מזהה חד-ערכי' };
  }

  // סכום החיוב הבודד המצופה מרשומת תשלום נתונה
  function expectedInstallment(pay) {
    const total = parseFloat(pay.pcfNeedToPayIncludingVat) || 0;
    const cnt = parseInt(pay.pcfNumberOfPayments, 10) || 1;
    return cnt > 0 ? round2(total / cnt) : total;
  }
  function hasPending(pay) { return pendingDocsFor(pay.customobject1039id).length > 0; }

  function findSourcePayment() {
    if (txPayment) return txPayment;
    // 🔴 חיוב הוראת קבע נושא directDebitId — מזהה חד-ערכי של ההוראה.
    // אם לא נמצאה רשומה איתו, **אסור** לנחש לפי סכום: הניחוש עלול לזקוף את
    // החיוב לתוכנית תשלומים אחרת של אותה לקוחה ולסמן תשלום עתידי כנפרע.
    // (נתפס חי 19/08 — חיוב הו"ק עדכן תיעוד של תוכנית 6 שבועות.)
    if (S(ev.directDebitId)) {
      const byDD = openPays.find((p) => S(p.pcfID) === S(ev.directDebitId));
      return byDD || null;
    }
    // 🔴 מכאן והלאה — **רק מזהים**. אין דירוג לפי סכום ואין "התוכנית האחרונה
    //    שנפתחה": שתיהן זקפו חיוב לתוכנית הלא נכונה וסימנו תשלום עתידי כנפרע.
    //    (נתפס חי 19/08.) אם אין מזהה שמקשר — אין שיוך, ונפתחת משימה לנציג.
    const byKey = (fn) => openPays.find(fn) || null;
    if (S(ev.asmachta)) {
      const m = byKey((p) => S(p.pcfExternalSoftwareID1) === `GROW-${S(ev.asmachta)}`);
      if (m) return m;
    }
    if (S(ev.transactionCode)) {
      const m = byKey((p) => S(p.pcfExternalSoftwareID2) === S(ev.transactionCode)
                          || S(p.pcfID) === S(ev.transactionCode));
      if (m) return m;
    }
    if (S(ev.transactionId)) {
      const m = byKey((p) => S(p.pcfID) === S(ev.transactionId));
      if (m) return m;
    }
    return null;
  }

  // תשלום רגיל: האם זה למעשה תשלום 2+ מתוך פריסה קיימת?
  if (branch === 'PAYMENT') {
    const src = findSourcePayment();
    if (src && S(src.pcfID) !== S(ev.transactionId)) {
      const pend = pendingDocsFor(src.customobject1039id);
      const perInst = round2((ev.grossTotal || 0));
      const expected = round2((parseFloat(src.pcfNeedToPayIncludingVat) || 0) / (parseInt(src.pcfNumberOfPayments, 10) || 1));
      if (pend.length > 0 && Math.abs(perInst - expected) <= 1) {
        branch = 'INSTALLMENT_CHARGE';
        decisions.push(`זוהה תשלום המשך מתוך פריסה קיימת (תשלום מקור ${S(src.customobject1039id)}, סכום מצופה ${expected}).`);
      }
    }
  }

  // 🔴 דיווח על כישלון זיהוי מוצר — חייב לקרות **אחרי** בדיקת הכפילות
  //    (כדי לא לפתוח משימה על מסירה חוזרת) ולפני הענפים, כדי שיחול על כולם.
  if (productUnidentified && !dup && !dupPayDoc) {
    warnings.push(`🔴 לא זוהה מוצר עבור התשלום. תיאור החיוב מגרואו: "${ev.growProductName || ev.descriptionText || '(ריק)'}". ` +
      'הרשומות נכתבות עם "מוצר לא מזוהה", ו**שרשרת הקמת המוצר לא תרוץ** — אין ליווי, אין קבוצה, אין תפריט ואין הודעת וולקאם.');
    taskOp('taskNoProduct', `לא זוהה מוצר ברכישה · ${custLabel}`,
      `התקבל תשלום שלא ניתן היה לשייך לאף מוצר בקטלוג, ולכן שרשרת הקמת המוצר לא רצה.\n\n` +
      `תיאור החיוב בגרואו: "${ev.growProductName || ev.descriptionText || '(ריק)'}"\n` +
      `סכום: ${money(ev.grossTotal)} · אסמכתא: ${ev.asmachta || '—'}\n\n` +
      `🔴 מה צריך לעשות:\n` +
      `1. לזהות איזה מוצר נרכש, ולעדכן אותו ברשומת התשלום ובתהליך המכירה.\n` +
      `2. להקים ידנית את מה שלא קם: תהליך ליווי, שיוך לקבוצה, תפריט והודעת וולקאם.\n\n` +
      `למניעה בפעם הבאה: תיאור התשלום בגרואו חייב להכיל את שם המוצר כפי שהוא בקטלוג ` +
      `(למשל "תוכנית המשך אונליין"), או שיוגדר מזהה GROW על המוצר בפיירברי.\n` +
      `ריצה: ${ev.executionUrl}`);
  }

  // ============================ ענף A — רכישה רגילה, תשלום חדש ============================
  if (branch === 'PAYMENT') {
    if (!ev.isSuccess) {
      return [{ json: { ...ev, branch: 'PAYMENT_FAILED', ops: [], warnings, decisions,
        summary: 'התשלום לא עבר — לא נוצרה שום רשומה בפיירברי.',
        accountid, accountName: custLabel, accountEmail, saleid, productName, productId, ownerid } }];
    }
    const n = ev.installmentsTotal;
    const payName = `התשלום של ${custLabel} | ${productName} | ${money(ev.grossTotal)} | ${n} תשלומים`;
    const lastChargeDate = n > 1
      ? addMonthsISO(ev.paymentDateISO, (n - 1) * (cfg.INSTALLMENT_INTERVAL_MONTHS || 1))
      : ev.paymentDateISO;
    const payRef = add({
      ref: 'payment', kind: 'create', object: '1039', label: 'יצירת תשלום (1039)',
      body: buildPaymentBody({
        name: payName, chargeId: ev.chargeId, paymentType: ev.fbPaymentType,
        // רכישה בתשלום אחד = "רגיל" · פריסה ל-2+ תשלומים = "תשלומים".
        paymentCategory: n > 1 ? 2 : 1,
        // תשלום אחד שנפרע ⇒ הרשומה נסגרת מיד. פריסה ⇒ נשארת "בתהליך פירעון".
        status: n === 1 ? 2 : 1,
        numberOfPayments: n, net: ev.netTotal, gross: ev.grossTotal,
        firstPaymentDate: ev.paymentDateISO, idemKey: ev.idemKeyBase,
        lastPaymentDate: lastChargeDate,
        nextPaymentDate: n > 1 ? addMonthsISO(ev.paymentDateISO, cfg.INSTALLMENT_INTERVAL_MONTHS || 1) : null,
      }),
    });

    // 🔴 אומת חי 19/08: גרואו שולח את לוח החיובים המדויק — firstPaymentSum
    // ו-periodicalPaymentSum. חלוקה שווה בסכום הכולל מייצרת סכומים שגויים
    // (למשל 2.35 ב-4 תשלומים = 0.61 + 0.58×3, ולא 0.5875×4).
    const vatDiv = 1 + (ev.vatPercent / 100);
    const usesGrowSchedule = n > 1 && ev.firstPayGross > 0 && ev.periodicalGross > 0 &&
      Math.abs(ev.firstPayGross + ev.periodicalGross * (n - 1) - ev.grossTotal) <= 0.05;
    if (usesGrowSchedule) {
      decisions.push(`לוח החיובים נלקח מגרואו: ${ev.firstPayGross} ראשון + ${ev.periodicalGross} × ${n - 1}.`);
    }
    for (let i = 0; i < n; i++) {
      const grossPer = usesGrowSchedule
        ? (i === 0 ? ev.firstPayGross : ev.periodicalGross)
        : round2(ev.grossTotal / n);
      add({
        ref: `doc${i + 1}`, kind: 'create', object: '1018',
        label: `יצירת תיעוד תשלום ${i + 1}/${n} (1018)`,
        body: buildDocBody({
          name: `תיעוד התשלום של ${custLabel} | ${productName}`,
          status: i === 0 ? 1 : 3,                 // 1 נפרע בהצלחה · 3 ממתין לפירעון
          paymentType: ev.fbPaymentType,
          net: round4(grossPer / vatDiv), gross: grossPer,
          // תאריך החיוב של כל תשלום — הראשון היום, והבאים בהפרש חודשי.
          paymentDate: i === 0
            ? ev.paymentDateISO
            : addMonthsISO(ev.paymentDateISO, i * (cfg.INSTALLMENT_INTERVAL_MONTHS || 1)),
          paymentRef: payRef,
          idemKey: `${ev.idemKeyBase}-${i + 1}`,
        }),
      });
    }

    const noteHtml = `<div dir="rtl">התשלום נוצר אוטומטית לאחר קליטת תשלום מ-GROW.<br>` +
      `מוצר: <b>${productName}</b> · סכום: <b>${money(ev.grossTotal)}</b> · ${n} תשלומים · אסמכתא: ${ev.asmachta || '—'}` +
      couponLine + `<br>ריצת n8n: ${execLink}</div>`;
    noteOp('note', noteHtml);
    // הערה גם על רשומת התשלום עצמה ועל כל תיעוד תשלום (דרישת אליאל 19/08)
    // 🔴 מושמט כשהחשבון נוצר באותה ריצה (accountNewlyCreated): פעולת התשלום
    // עצמה כבר תלויה גם בחשבון החדש וגם בעסקה החדשה (שני refs, לא אחד),
    // ולכן היא נופלת לגל 3 — והערה שתלויה *בה* תצטרך גל רביעי שלא קיים
    // במנגנון (ראו "הפרדת פעולת האב": שלושה גלים ליניאריים בלבד).
    // ההערה הכללית על תהליך המכירה (למעלה) כבר נושאת את אותו תוכן בדיוק,
    // כך שהמידע לא הולך לאיבוד — רק לא משוכפל על התשלום/התיעוד עצמם.
    if (!accountNewlyCreated) {
      noteOn('notePay', payRef, 1039, 'הערה על רשומת התשלום', noteHtml);
      for (let i = 0; i < n; i++) {
        noteOn(`noteDoc${i + 1}`, `@doc${i + 1}`, 1018,
          `הערה על תיעוד תשלום ${i + 1}/${n}`,
          `<div dir="rtl">תיעוד התשלום נוצר אוטומטית לאחר תשלום מ-GROW.<br>` +
          `מוצר: <b>${productName}</b> · תשלום ${i + 1} מתוך ${n}` + couponLine +
          `<br>ריצת n8n: ${execLink}</div>`);
      }
    }

    if (!accountFound || !saleFound) {
      taskOp('taskLink', `שיוך ידני לתשלום מ-GROW · ${custLabel}`,
        `התקבל תשלום מגרואו שלא ניתן היה לשייך אוטומטית.\n` +
        `${!accountFound ? '• לא נמצאה לקוחה לפי הטלפון ' + (ev.phone || '(חסר)') + '\n' : ''}` +
        `${!saleFound ? '• לא נמצא תהליך מכירה פתוח\n' : ''}` +
        `סכום: ${money(ev.grossTotal)} · מוצר: ${productName} · אסמכתא: ${ev.asmachta}\n` +
        `שם מגרואו: ${ev.fullName} · טלפון: ${ev.phone}\nריצה: ${ev.executionUrl}`);
    }

    decisions.push('ענף A — רכישה רגילה, תשלום חדש');
    return [{ json: { ...ev, branch: 'NEW_PURCHASE', ops, warnings, decisions,
      summary: `נוצר תשלום אחד ו-${n} תיעודי תשלום.`,
      accountid, accountName: custLabel, accountEmail, saleid, productName, productId, ownerid,
      nextWorkflowUrl: cfg.PRODUCT_SETUP_WEBHOOK_URL } }];
  }

  // ============ ענף B — תשלום קיים מתוך פריסה · ענף D — חיוב מתוך הו"ק · ענף F — כשל ============
  if (branch === 'INSTALLMENT_CHARGE' || branch === 'RECURRING_CHARGE' || branch === 'RECURRING_FAILED') {
    let src = findSourcePayment();

    // ============================================================================
    // חיוב הו"ק שאין לו רשומת הוראת קבע בפיירברי — שני מקרים שונים לגמרי:
    //
    //   א. ההוראה **הוקמה ברגע זה** (הלקוחה עברה בעמוד תשלום).
    //      אומת חי 20/08: paymentSource="Payment Links".
    //      זו רכישה חדשה לכל דבר ⇒ נוצרת רשומת הו"ק, נרשם החיוב הראשון,
    //      ומופעל התהליך המקצועי להקמת המוצר.
    //      🔴 גרואו **לא** שולחת וובהוק הקמה נפרד — החיוב הראשון הוא האירוע היחיד.
    //
    //   ב. חיוב חוזר של הוראה **ותיקה** שהוקמה לפני המערכת.
    //      paymentSource="מערכת חיצונית". הרשומה נוצרת רטרואקטיבית עם
    //      pcfID = מזהה ההו"ק בגרואו, שהוא מפתח האיחוד במעבר הנתונים.
    // ============================================================================
    // ג. ההוראה הוקמה **ידנית מתוך מערכת גרואו** (בק-אופיס). paymentSource
    //    זהה לחיוב חוזר, אבל מזהה ההו"ק אינו מוכר לפיירברי — כלומר זו הוראה
    //    חדשה, ולכן רכישה חדשה לכל דבר. (אליאל, 14/09/2026)
    const soFromBackOffice = !src && ev.isBackOfficeSource === true && S(ev.directDebitId) && ev.isSuccess;
    const soIsNewSetup = (!src && ev.isSetupSource === true && S(ev.directDebitId) && ev.isSuccess)
      || soFromBackOffice;

    if (!src && ev.eventType === 'RECURRING_CHARGE' && S(ev.directDebitId) && ev.isSuccess
        && (soIsNewSetup || cfg.SELF_HEAL_STANDING_ORDER)) {
      const monthlyGross = round2(ev.grossTotal);
      const retroTag = soIsNewSetup ? '' : (cfg.RETRO_PREFIX || '');
      const soRef = add({
        ref: 'payment', kind: 'create', object: '1039',
        label: soIsNewSetup ? 'יצירת הוראת קבע (1039)' : 'יצירת רשומת הוראת קבע רטרואקטיבית',
        body: buildPaymentBody({
          name: `${retroTag}הוראת הקבע של ${custLabel} | ${productName} | ${money(monthlyGross)} | חיוב חודשי`,
          // 🔴 08/09/2026 — "הוראת קבע" היא סוג תשלום, לא אמצעי תשלום. אמצעי
          // התשלום בפועל לא ידוע מהאירוע של גרואו ⇒ ברירת מחדל אשראי (1),
          // כפי שאליאל תיקן ידנית ברטרו על 364 הרשומות הקיימות ב-1039.
          chargeId: ev.directDebitId, paymentType: 1, paymentCategory: 3,
          numberOfPayments: soCountOnCreate(),
          net: round4(monthlyGross / (1 + ev.vatPercent / 100)), gross: monthlyGross,
          firstPaymentDate: ev.paymentDateISO,
          idemKey: `GROW-DD-${ev.directDebitId}`,
        }),
      });
      addSoCountUpdate(soRef);
      add({
        ref: 'doc1', kind: 'create', object: '1018', label: 'יצירת תיעוד תשלום הו"ק (1018)',
        body: buildDocBody({
          name: `תיעוד התשלום הו"ק של ${custLabel} | ${productName}`,
          status: 1, paymentType: 1,
          net: round4(monthlyGross / (1 + ev.vatPercent / 100)), gross: monthlyGross,
          paymentDate: ev.paymentDateISO, paymentRef: soRef, idemKey: ev.idemKeyBase,
        }),
      });
      if (soIsNewSetup) {
        decisions.push(soFromBackOffice
          ? 'הוראת הקבע הוקמה ידנית מתוך מערכת גרואו — מזהה ההוראה לא היה מוכר לפיירברי, ולכן זו רכישה חדשה.'
          : 'הוראת הקבע הוקמה עכשיו (מקור התשלום: עמוד תשלום) — נוצרה רשומת הוראת קבע ונרשם החיוב הראשון.');
        noteOp('note', `<div dir="rtl">${soFromBackOffice ? 'הוקמה הוראת קבע ידנית במערכת גרואו' : 'הוקמה הוראת קבע ב-GROW'} ונקלט החיוב הראשון.<br>` +
          `מוצר: <b>${productName}</b> · חיוב חודשי: <b>${money(monthlyGross)}</b> · מזהה הו"ק: ${ev.directDebitId}` +
          couponLine + `<br>ריצת n8n: ${execLink}</div>`);
        noteOn('notePay', soRef, 1039, 'הערה על רשומת הוראת הקבע',
          `<div dir="rtl">רשומת הוראת הקבע נוצרה אוטומטית מהחיוב הראשון.<br>` +
          `מזהה הו"ק בגרואו: ${ev.directDebitId}<br>ריצת n8n: ${execLink}</div>`);
        if (!accountFound || !saleFound) {
          taskOp('taskLink', `שיוך ידני להוראת קבע מ-GROW · ${custLabel}`,
            `הוקמה הוראת קבע בגרואו שלא ניתן היה לשייך אוטומטית.\n` +
            `${!accountFound ? '• לא נמצאה לקוחה לפי הטלפון ' + (ev.phone || '(חסר)') + '\n' : ''}` +
            `${!saleFound ? '• לא נמצא תהליך מכירה פתוח\n' : ''}` +
            `חיוב חודשי: ${money(monthlyGross)} · מוצר: ${productName}\nריצה: ${ev.executionUrl}`);
        }
        // 🔴 רכישה חדשה ⇒ מפעילים את התהליך המקצועי להקמת המוצר.
        return [{ json: { ...ev,
          branch: soFromBackOffice ? 'STANDING_ORDER_BACKOFFICE' : 'STANDING_ORDER_SETUP',
          ops, warnings, decisions,
          summary: soFromBackOffice
            ? 'הוקמה הוראת קבע מתוך מערכת גרואו ונרשם החיוב הראשון.'
            : 'הוקמה הוראת קבע ונרשם החיוב הראשון.',
          accountid, accountName: custLabel, accountEmail, saleid, productName, productId, ownerid,
          nextWorkflowUrl: cfg.PRODUCT_SETUP_WEBHOOK_URL } }];
      }

      warnings.push(`לא נמצאה רשומת הוראת קבע עם מזהה ${ev.directDebitId} — נוצרה רשומה רטרואקטיבית מתוך נתוני החיוב. יש לאמת את הסכום ואת תאריך ההקמה.`);
      taskOp('taskAutoSO', `אימות הוראת קבע שנוצרה אוטומטית · ${custLabel}`,
        `התקבל חיוב הוראת קבע שלא נמצאה לו רשומה בפיירברי, ולכן ההוראה נוצרה רטרואקטיבית.\n` +
        `מזהה הו"ק בגרואו: ${ev.directDebitId} · חיוב: ${money(monthlyGross)} · אסמכתא: ${ev.asmachta}\n\n` +
        `🔴 במעבר הנתונים יש לאחד את הרשומה הזו עם ההוראה מה-CRM הישן\n` +
        `לפי מזהה ההו"ק (שדה "מזהה" ברשומת התשלום) — ולא ליצור רשומה שנייה.\n\n` +
        `יש לאמת מול גרואו את תאריך ההקמה, הסכום החודשי והמוצר.\nריצה: ${ev.executionUrl}`);
      decisions.push('ענף D — חיוב הו"ק · רשומת ההוראה נוצרה רטרואקטיבית');
      noteOp('note', `<div dir="rtl">התקבל חיוב הוראת קבע מ-GROW.<br>` +
        `מוצר: <b>${productName}</b> · סכום: <b>${money(monthlyGross)}</b> · מזהה הו"ק: ${ev.directDebitId}<br>` +
        `<i>רשומת ההוראה לא הייתה קיימת ונוצרה אוטומטית — לאיחוד במעבר הנתונים.</i><br>ריצת n8n: ${execLink}</div>`);
      return [{ json: { ...ev, branch: 'STANDING_ORDER_SELF_HEAL', ops, warnings, decisions,
        summary: 'נוצרה רשומת הוראת קבע רטרואקטיבית ותיעוד תשלום לחיוב שהתקבל.',
        accountid, accountName: custLabel, accountEmail, saleid, productName, productId, ownerid } }];
    }

    if (!src) {
      // 🔴 עד לאחר מעבר הנתונים מה-CRM הישן — המשימה היא הרשומה היחידה שנוצרת.
      //    היא נושאת את כל מה שנדרש כדי להשלים את השיוך אחרי המעבר:
      //    טלפון + סכום + 4 ספרות הכרטיס = צירוף חד-ערכי לכל הוראת קבע ב-GROW.
      taskOp('taskNoSrc', `[להשלמה אחרי המעבר] חיוב מגרואו ללא רשומת תשלום · ${custLabel}`,
        `התקבל חיוב המשך מגרואו אך לא נמצאה רשומת "תשלום" (1039) מקושרת.\n` +
        `ההוראה/הפריסה הוקמה לפני שהמערכת הזו עלתה. הרשומה תגיע במעבר הנתונים (04–05/09).\n\n` +
        `סוג אירוע: ${ev.eventType} · מזהה הו"ק: ${ev.directDebitId || '—'} · אסמכתא: ${ev.asmachta || '—'}\n` +
        `סכום: ${money(ev.grossTotal)} · טלפון: ${ev.phone} · 4 ספרות: ${ev.cardSuffix || '—'}\n` +
        `מוצר: ${productName} · תיאור בגרואו: ${ev.growProductName || ev._raw?.paymentDesc || '—'}\n` +
        `ריצה: ${ev.executionUrl}`);
      warnings.push('לא נמצאה רשומת תשלום מקור — נפתחה משימה בלבד.');
      return [{ json: { ...ev, branch: branch + '_NO_SOURCE', ops, warnings, decisions,
        summary: 'לא נמצאה רשומת תשלום מקור — נפתחה משימה לטיפול ידני.',
        accountid, accountName: custLabel, accountEmail, saleid, productName, productId, ownerid } }];
    }

    const srcType = pickNum(src.pcfPaymentType, PT_LABELS);
    const srcCategory = pickNum(src.pcfPaymentCategory, PC_LABELS);
    const srcId = S(src.customobject1039id);
    // 🔴 08/09/2026 — הזיהוי "האם זו הוראת קבע" עבר מ"אמצעי תשלום"=7 ל"סוג
    // תשלום"=3 (השדה הנכון). srcType===7 נשאר כרשת ביטחון לרשומות שטרם
    // הוגרו/תוקנו (למשל מהמעבר מה-CRM הישן) ואין להן עדיין pcfPaymentCategory.
    const isStandingOrder = srcCategory === 3 || srcType === 7;
    const paid = ev.isSuccess;

    if (isStandingOrder && branch !== 'RECURRING_FAILED') {
      // ---- ענף D: תשלום חדש מתוך הוראת קבע קיימת → יוצרים תיעוד תשלום חדש ----
      add({
        ref: 'doc1', kind: 'create', object: '1018', label: 'יצירת תיעוד תשלום הו"ק (1018)',
        body: buildDocBody({
          name: `תיעוד התשלום הו"ק של ${custLabel} | ${productName}`,
          status: paid ? 1 : 4,
          paymentType: 1,
          net: ev.netTotal, gross: ev.grossTotal,
          paymentDate: paid ? ev.paymentDateISO : null,
          paymentRef: srcId,
          idemKey: ev.idemKeyBase,
        }),
      });
      decisions.push('ענף D — חיוב מתוך הוראת קבע קיימת');
    } else {
      // ---- ענף B / F: עדכון תיעוד תשלום קיים שממתין לפירעון ----
      // 🔴 הבחירה נעשית **לפי מזהה התיעוד בלבד**. אין "הראשון ברשימה".
      const sel = selectInstallmentTarget(srcId);
      const target = sel.target;
      if (sel.why) decisions.push(sel.why);
      if (sel.note) warnings.push(sel.note);

      if (!target && sel.blocked) {
        // אסור לנחש: לא נוגעים בשום רשומה קיימת ולא יוצרים רשומה כספית חדשה.
        warnings.push('לא ניתן היה לזהות בוודאות את התשלום שנפרע — לא בוצע שום עדכון.');
        taskOp('taskAmbiguous', `חיוב מגרואו שלא ניתן לשייך לתשלום ספציפי · ${custLabel}`,
          `התקבל חיוב על סך ${money(ev.grossTotal)} תחת תשלום ${srcId},\n` +
          `אך יש יותר מתיעוד תשלום אחד שממתין לפירעון ולאף אחד מהם אין מזהה תשלום.\n` +
          `אסור לנחש — יש לסמן ידנית איזה תשלום נפרע.\n` +
          `אסמכתא: ${ev.asmachta || '—'} · תאריך: ${ev.paymentDateISO || '—'}\nריצה: ${ev.executionUrl}`);
        return [{ json: { ...ev, branch: 'INSTALLMENT_AMBIGUOUS', ops, warnings, decisions, sourcePaymentId: srcId,
          summary: 'לא ניתן היה לזהות בוודאות איזה תשלום נפרע — נפתחה משימה, לא בוצע עדכון.',
          accountid, accountName: custLabel, accountEmail, saleid, productName, productId, ownerid } }];
      }

      if (!target) {
        warnings.push('לא נמצא תיעוד תשלום שממתין לפירעון תחת התשלום המקור — נוצר תיעוד חדש במקום עדכון.');
        add({
          ref: 'doc1', kind: 'create', object: '1018', label: 'יצירת תיעוד תשלום (חלופה לעדכון)',
          body: buildDocBody({
            name: `תיעוד התשלום של ${custLabel} | ${productName}`,
            // 🔴 08/09/2026 — לענף הזה מגיעים רק כשאין הוראת קבע (isStandingOrder=false),
            // אך srcType עדיין עלול לשאת את הערך הישן 7 ברשומות שטרם תוקנו —
            // ולכן אסור להעביר אותו כמו שהוא הלאה כ"אמצעי תשלום".
            status: paid ? 1 : 4,
            paymentType: srcType === 7 ? 1 : (srcType || ev.fbPaymentType),
            net: ev.netTotal, gross: ev.grossTotal,
            paymentDate: paid ? ev.paymentDateISO : null,
            paymentRef: srcId, idemKey: ev.idemKeyBase,
          }),
        });
      } else {
        const upd = {
          pcfPaymetStatus: paid ? 1 : 4,
          pcfsStatusUpdateTime: ev.nowISO,
          pcfExternalSoftwareID1: ev.idemKeyBase,
        };
        if (S(ev.asmachta)) upd.pcfReference = S(ev.asmachta);
        if (paid) upd.pcfPaymentDate = ev.paymentDateISO;
        add({
          ref: 'docUpdate', kind: 'update', object: '1018',
          recordId: S(target.customobject1018id), label: 'עדכון סטטוס תיעוד תשלום (1018)',
          body: upd,
        });
      }
      decisions.push(paid ? 'ענף B — תשלום המשך שנפרע בהצלחה' : 'ענף B/F — תשלום המשך שלא עבר');
    }

    // ── סגירת רשומת התשלום כשכל התיעודים נפרעו ──────────────────────────
    // רק לפריסות אשראי. הוראת קבע היא פתוחה מעצם טבעה ולעולם לא נסגרת כאן.
    if (paid && srcId && !isStandingOrder) {
      const allDocs = docsOfPayment(srcId);
      const settledId = ops.find((o) => o.ref === 'docUpdate')
        ? S(ops.find((o) => o.ref === 'docUpdate').recordId) : '';
      const stillOpen = allDocs.filter((x) => S(x.customobject1018id) !== settledId &&
        pickNum(x.pcfPaymetStatus, DS_LABELS) !== 1);
      if (settledId && allDocs.length && !stillOpen.length) {
        add({ ref: 'payClose', kind: 'update', object: '1039', recordId: srcId,
          label: 'סגירת רשומת התשלום (1039) — כל התשלומים נפרעו',
          body: { pcfStatus: 2, pcfstatusupdatedate: ev.nowISO } });
        decisions.push('כל תיעודי התשלום תחת התשלום הזה נפרעו — הרשומה סומנה כ"נפרע בהצלחה".');
      }
    }

    if (!paid) {
      taskOp('taskFail', `תשלום לא עבר · ${custLabel} · ${money(ev.grossTotal)}`,
        `חיוב מגרואו נכשל ודורש טיפול.\n` +
        `סיבה: ${ev.failureMessage || 'לא צוינה'} · ניסיונות חיוב: ${ev.chargeAttempts || '—'}\n` +
        `מוצר: ${productName} · תשלום מקור: ${srcId}\nריצה: ${ev.executionUrl}`);
    }

    const chargeNote = `<div dir="rtl">${paid ? 'התקבל חיוב' : '⚠️ חיוב נכשל'} מ-GROW ועודכן אוטומטית.<br>` +
      `מוצר: <b>${productName}</b> · סכום: <b>${money(ev.grossTotal)}</b> · אסמכתא: ${ev.asmachta || '—'}` +
      `${paid ? '' : '<br>סיבה: ' + (ev.failureMessage || 'לא צוינה')}` + couponLine +
      `<br>ריצת n8n: ${execLink}</div>`;
    noteOp('note', chargeNote);
    // הערה על תיעוד התשלום עצמו — בין אם נוצר חדש ובין אם עודכן קיים
    const docTarget = ops.find((o) => o.ref === 'docUpdate') ? ops.find((o) => o.ref === 'docUpdate').recordId
                    : (ops.find((o) => o.ref === 'doc1') ? '@doc1' : '');
    if (docTarget) noteOn('noteDoc', docTarget, 1018, 'הערה על תיעוד התשלום', chargeNote);
    // הערה על רשומת התשלום המקורית
    if (srcId) noteOn('notePay', srcId, 1039, 'הערה על רשומת התשלום', chargeNote);

    return [{ json: { ...ev, branch: isStandingOrder && branch !== 'RECURRING_FAILED' ? 'STANDING_ORDER_CHARGE' : 'INSTALLMENT_UPDATE',
      ops, warnings, decisions, sourcePaymentId: srcId,
      summary: paid ? 'תיעוד התשלום עודכן/נוצר כנפרע בהצלחה.' : 'תיעוד התשלום סומן כלא עבר ונפתחה משימה לנציג.',
      accountid, accountName: custLabel, accountEmail, saleid, productName, productId, ownerid } }];
  }

  // ============================ ענף C — הקמת הוראת קבע ============================
  if (branch === 'STANDING_ORDER_SETUP') {
    if (!ev.isSuccess) {
      return [{ json: { ...ev, branch: 'STANDING_ORDER_FAILED', ops: [], warnings, decisions,
        summary: 'הקמת הוראת הקבע לא הצליחה — לא נוצרה שום רשומה.',
        accountid, accountName: custLabel, accountEmail, saleid, productName, productId, ownerid } }];
    }
    const monthlyGross = round2(ev.periodicalGross || ev.grossTotal);
    const monthlyNet = round4(monthlyGross / (1 + ev.vatPercent / 100));
    const payName = `הוראת הקבע של ${custLabel} | ${productName} | ${money(monthlyGross)} | חיוב חודשי`;
    const payRef = add({
      ref: 'payment', kind: 'create', object: '1039', label: 'יצירת הוראת קבע (1039)',
      body: buildPaymentBody({
        name: payName,
        chargeId: ev.directDebitId || ev.chargeId,
        paymentType: 1, paymentCategory: 3, numberOfPayments: soCountOnCreate(),
        net: monthlyNet, gross: monthlyGross,
        firstPaymentDate: ev.paymentDateISO, idemKey: ev.idemKeyBase,
      }),
    });
    addSoCountUpdate(payRef);

    if (cfg.CREATE_DOC_ON_STANDING_ORDER_SETUP) {
      add({ ref: 'doc1', kind: 'create', object: '1018', label: 'יצירת תיעוד תשלום ראשון להו"ק',
        body: buildDocBody({
          name: `תיעוד התשלום הו"ק של ${custLabel} | ${productName}`,
          status: 1, paymentType: 1, net: monthlyNet, gross: monthlyGross,
          paymentDate: ev.paymentDateISO, paymentRef: payRef, idemKey: `${ev.idemKeyBase}-1`,
        }) });
    } else {
      warnings.push('לפי האפיון — בהקמת הוראת קבע לא נוצר תיעוד תשלום. החיוב הראשון ייקלט כאירוע חיוב נפרד.');
    }

    const soNote = `<div dir="rtl">הוראת קבע נוצרה אוטומטית לאחר הקמה ב-GROW.<br>` +
      `מוצר: <b>${productName}</b> · חיוב חודשי: <b>${money(monthlyGross)}</b> · מזהה הו"ק: ${ev.directDebitId || '—'}` +
      couponLine + `<br>ריצת n8n: ${execLink}</div>`;
    noteOp('note', soNote);
    noteOn('notePay', payRef, 1039, 'הערה על רשומת הוראת הקבע', soNote);

    if (!accountFound || !saleFound) {
      taskOp('taskLink', `שיוך ידני להוראת קבע מ-GROW · ${custLabel}`,
        `הוקמה הוראת קבע בגרואו שלא ניתן היה לשייך אוטומטית.\n` +
        `${!accountFound ? '• לא נמצאה לקוחה לפי הטלפון ' + (ev.phone || '(חסר)') + '\n' : ''}` +
        `${!saleFound ? '• לא נמצא תהליך מכירה פתוח\n' : ''}` +
        `חיוב חודשי: ${money(monthlyGross)} · מוצר: ${productName}\nריצה: ${ev.executionUrl}`);
    }

    decisions.push('ענף C — הקמת הוראת קבע');
    return [{ json: { ...ev, branch: 'STANDING_ORDER_SETUP', ops, warnings, decisions,
      summary: 'נוצרה רשומת הוראת קבע.',
      accountid, accountName: custLabel, accountEmail, saleid, productName, productId, ownerid,
      nextWorkflowUrl: cfg.PRODUCT_SETUP_WEBHOOK_URL } }];
  }

  // ============================ ענף E — מסמך חשבונאי ============================
  if (branch === 'INVOICE') {
    const prefixMapEarly = cfg.DOC_TYPE_BY_PREFIX || {};
    const numEarly = S(ev.invoiceNumber);
    const docTypeEarly = prefixMapEarly[numEarly.slice(0, 2)] || ctx.docTypeLabel ||
                         cfg.DOC_TYPE_DEFAULT || 'מסמך חשבונאי';

    if (!txPayment) {
      // ============================================================================
      // 🔴 20/08/2026 — מסמך שלא שויך **עדיין נשמר**.
      // קודם נפתחה רק משימה, והמסמך עצמו נעלם מהמערכת לגמרי (נתפס חי בזיכוי
      // של סער). זה לא ניחוש: מספר המסמך, הסוג והקישור ידועים בוודאות —
      // מה שלא ידוע הוא הלקוחה והתשלום, ואותם פשוט לא כותבים.
      // ============================================================================
      // ── שיוך מתוך גוף ה-PDF ─────────────────────────────────────────
      // 🔴 שני מזהים חד-ערכיים **מודפסים** במסמך, ולכן מותרים לשיוך:
      //    1. מספר המסמך המקורי — "זיכוי עבור חשבונית מס קבלה מספר 49680".
      //    2. טלפון הלקוחה (הוזרם כבר לחיפוש הלקוחה בשלב מוקדם יותר).
      //    אין כאן ניחוש: שניהם כתובים במסמך עצמו.
      // 🔴 שני נתיבים לאיתור המסמך המקורי לפי המספר שמודפס בזיכוי:
      //    א. רשומת מסמך (1038) עם GROW-INV-{מספר} — מסמכים שנקלטו במערכת הזו.
      //    ב. תיעוד תשלום (1018) שבשדה "מספר מסמך" שלו מופיע אותו מספר —
      //       כך נתפסים גם מסמכים שהגיעו מה-CRM הישן ואין להם רשומת 1038.
      const refLabel = S(ev.docRefType) ? `${S(ev.docRefType)} ${S(ev.docRefNumber)}` : S(ev.docRefNumber);
      const srcDoc = S(ev.docRefNumber)
        ? refDocs.find((d) => S(d.pcfExternalSoftwareID1) === `GROW-INV-${S(ev.docRefNumber)}`)
        : null;
      const srcRec = (!srcDoc && S(ev.docRefNumber))
        ? refRecs.find((d) => S(d.pcfInvoiceNumber1) === S(ev.docRefNumber))
        : null;

      const linkAccount = S(srcDoc && srcDoc.pcfaccountid) ||
                          S(srcRec && srcRec.pcfAccountid) || accountid;
      const linkPayment = S(srcDoc && srcDoc.pcfPaymentCollection) ||
                          S(srcRec && srcRec.pcfPaymentCollection);
      const linkRecord  = S(srcDoc && srcDoc.pcfPaymentRecord) ||
                          S(srcRec && srcRec.customobject1018id);
      const linkSale    = S(srcDoc && srcDoc.pcfLinkedSale) ||
                          S(srcRec && srcRec.pcfSale) || saleid;

      if (srcDoc) {
        decisions.push(`המסמך המקורי (${refLabel}) זוהה לפי רשומת המסמך — השיוך הועתק ממנו.`);
      } else if (srcRec) {
        decisions.push(`המסמך המקורי (${refLabel}) זוהה לפי "מספר מסמך" בתיעוד התשלום — השיוך הועתק ממנו.`);
      } else if (S(ev.docRefNumber)) {
        warnings.push(`במסמך מופיעה הפניה ל${refLabel ? '-' + refLabel : 'מסמך ' + S(ev.docRefNumber)}, ` +
          'אך הוא לא נמצא בפיירברי — לא ברשומות המסמכים ולא בתיעודי התשלום.');
      }
      if (!srcDoc && accountFound && S(ev.docPhone)) {
        decisions.push(`הלקוחה זוהתה לפי הטלפון שמודפס במסמך (${S(ev.docPhone)}).`);
      }
      if (S(ev.docPhoneWhy)) warnings.push(`זיהוי טלפון מהמסמך: ${S(ev.docPhoneWhy)}`);
      if (ev.docTextFound === false && ev.eventType === 'INVOICE') {
        warnings.push('לא ניתן היה לקרוא את ה-PDF של המסמך — השיוך נעשה בלי נתוני המסמך.');
      }

      const matchedSomething = !!(linkAccount || linkPayment);

      let docRefUnmatched = '';
      if (cfg.CREATE_UNMATCHED_DOCUMENT !== false) {
        const ub = {
          name: cut(matchedSomething
            ? `${docTypeEarly} - ${ev.invoiceNumber} - ${custLabel}`
            : `${docTypeEarly} - ${ev.invoiceNumber} - ⚠️ לא משויך`, 190),
          pcfDocumentType: cut(docTypeEarly, 190),
          pcfLinkToDocument: S(ev.invoiceUrl),
          pcfCreatedByPersonOrSystem: 2,
          pcfExternalSoftwareID1: ev.idemKeyBase,
          pcfExternalSoftwareID2: 'GROW',
        };
        // 🔴 מה שלא זוהה בוודאות — לא נכתב.
        lookupOrOmit(ub, 'pcfaccountid', linkAccount);
        lookupOrOmit(ub, 'pcfLinkedSale', linkSale);
        lookupOrOmit(ub, 'pcfPaymentCollection', linkPayment);
        lookupOrOmit(ub, 'pcfPaymentRecord', linkRecord);
        docRefUnmatched = add({ ref: 'documentUnmatched', kind: 'create', object: '1038',
          label: matchedSomething ? 'יצירת מסמך (1038)' : 'יצירת מסמך לא משויך (1038)', body: ub });
        decisions.push(matchedSomething
          ? 'המסמך נשמר בפיירברי ושויך לפי המזהים שמודפסים בו.'
          : 'המסמך נשמר בפיירברי בלי שיוך — השיוך ידני.');
      }

      // ── רישום הזיכוי ────────────────────────────────────────────────
      // 🔴 אומת חי 20/08: השדות "סה"כ הוחזר" באובייקט 1039 הם **שדות מחושבים**.
      //    כתיבה אליהם מחזירה 200 ופשוט לא נשמרת — הם נגזרים מרשומות תיעוד
      //    התשלום. הדרך הנכונה לרשום זיכוי היא ליצור תיעוד תשלום בסטטוס
      //    "זיכוי בוצע בהצלחה" (2), ופיירברי מחשבת את הסכום בעצמה.
      //    נבדק: תיעוד זיכוי של 0.16 ⇒ "סה"כ הוחזר כולל מע"מ" התעדכן לבד.
      if (cfg.WRITE_REFUND_ON_CREDIT === true && ev.docIsCredit &&
          linkPayment && ev.docRefundAmount > 0) {
        const refundKey = `${ev.idemKeyBase}-REFUND`;
        const already = docs.find((x) => S(x.pcfExternalSoftwareID1) === refundKey);
        // 🔴 אומת חי 23/08: "סה"כ הוחזר" באובייקט 1039 מסוכם מכל תיעוד בסטטוס
        //    "זיכוי בוצע בהצלחה". אם גם התיעוד המקורי יסומן וגם ייווצר תיעוד
        //    זיכוי נפרד — הסכום נספר **פעמיים** (נמדד: 1.98 במקום 0.99).
        //    לכן תיעוד זיכוי נפרד נוצר **רק** כשהתיעוד המקורי לא זוהה.
        if (already) {
          decisions.push('תיעוד הזיכוי כבר קיים — לא נוצר שוב.');
        } else if (linkRecord) {
          decisions.push('הזיכוי נרשם על תיעוד התשלום המקורי — לא נוצר תיעוד נפרד (מונע ספירה כפולה).');
        } else {
          const gross = round2(ev.docRefundAmount);
          const rb = {
            name: cut(`זיכוי של ${custLabel} | ${docTypeEarly} ${ev.invoiceNumber}`, 190),
            pcfPaymetStatus: 2,                 // זיכוי בוצע בהצלחה
            pcfsStatusUpdateTime: ev.nowISO,
            pcfPaymentDate: ev.paymentDateISO || ev.nowISO,
            pcftaxincludecode: 1,
            pcfPayed: round4(gross / (1 + ev.vatPercent / 100)),
            pcfPayedIncludingVAT: gross,
            pcfInvoiceNumber1: S(ev.invoiceNumber),
            pcfCreatedByPersonOrSystem: 2,
            pcfExternalSoftwareID1: refundKey,
            pcfExternalSoftwareID2: 'GROW',
          };
          lookupOrOmit(rb, 'pcfAccountid', linkAccount);
          lookupOrOmit(rb, 'pcfPaymentCollection', linkPayment);
          lookupOrOmit(rb, 'pcfSale', linkSale);
          lookupOrOmit(rb, 'ownerid', ownerid);
          add({ ref: 'refund', kind: 'create', object: '1018',
            label: 'יצירת תיעוד זיכוי (1018)', body: rb });
          decisions.push(`נרשם תיעוד זיכוי של ${money(gross)} תחת התשלום — "סה"כ הוחזר" יתעדכן אוטומטית.`);
        }

        // ── עדכון תיעוד התשלום המקורי ────────────────────────────────
        // 🔴 דרישת אליאל 23/08: התיעוד שזוכה לא יכול להישאר "נפרע בהצלחה".
        //    מעדכנים גם את הסטטוס וגם את "סכום זיכוי" (pcfrefundtotal),
        //    כדי שיהיה אפשר להשוות מול "סכום ששולם" ולראות אם הזיכוי מלא.
        const origRec = linkRecord
          ? docs.find((x) => S(x.customobject1018id).toUpperCase() === linkRecord.toUpperCase())
          : null;
        const gross2 = round2(ev.docRefundAmount);
        const prevRefund = origRec ? Number(origRec.pcfrefundtotal || 0) : 0;

        if (!linkRecord) {
          warnings.push('לא זוהה תיעוד התשלום המקורי — הסטטוס שלו לא עודכן.');
        } else if (prevRefund > 0 && Math.abs(prevRefund - gross2) > 0.01) {
          // 🔴 זיכוי שני בסכום אחר — לא דורסים סכום קיים בשקט.
          warnings.push(`בתיעוד התשלום המקורי כבר רשום זיכוי של ${money(prevRefund)}, ` +
            `והמסמך הנוכחי הוא על ${money(gross2)}. הסכום לא נדרס.`);
          taskOp('taskRefundOnRefund', `זיכוי נוסף על תיעוד שכבר זוכה · ${custLabel}`,
            `התקבל ${docTypeEarly} ${ev.invoiceNumber} על סך ${money(gross2)},\n` +
            `אך בתיעוד התשלום המקורי כבר רשום זיכוי של ${money(prevRefund)}.\n` +
            `יש לקבוע ידנית את סכום הזיכוי המצטבר.\nריצה: ${ev.executionUrl}`);
        } else {
          const paidGross = origRec ? Number(origRec.pcfPayedIncludingVAT || 0) : 0;
          const partial = paidGross > 0 && gross2 + 0.01 < paidGross;
          add({ ref: 'origRefund', kind: 'update', object: '1018', recordId: linkRecord,
            label: 'עדכון תיעוד התשלום המקורי — זיכוי',
            body: { pcfPaymetStatus: 2, pcfrefundtotal: gross2, pcfsStatusUpdateTime: ev.nowISO } });
          decisions.push(partial
