          if (partial) {
            warnings.push(`זיכוי חלקי — ${money(gross2)} מתוך ${money(paidGross)}. נפתחה משימה לאימות.`);
            taskOp('taskPartialRefund', `זיכוי חלקי לבדיקה · ${custLabel} · ${docTypeEarly} ${ev.invoiceNumber}`,
