              `תיעוד התשלום סומן "זיכוי בוצע בהצלחה" ושדה "סכום זיכוי" מולא בסכום המדויק.\n` +
              `יש לוודא שזו אכן הכוונה.\nריצה: ${ev.executionUrl}`);
          }
        }
      } else if (ev.docIsCredit && !linkPayment) {
        warnings.push('זוהה מסמך זיכוי אך התשלום לא זוהה בוודאות — לא נרשם תיעוד זיכוי.');
      }

      taskOp('taskNoMatch', `${docTypeEarly} מגרואו ${matchedSomething ? 'לבדיקה' : 'ללא תשלום מתאים'} · מסמך ${ev.invoiceNumber} · ${custLabel}`,
        `התקבל מסמך מגרואו שלא ניתן היה לשייך לרשומת תשלום בפיירברי.\n\n` +
        `סוג המסמך: ${docTypeEarly}\n` +
        `מספר מסמך: ${ev.invoiceNumber}\n` +
        `קישור למסמך: ${ev.invoiceUrl}\n` +
        `מזהה העסקה שהמסמך שלח: ${ev.transactionCode}\n\n` +
        (docRefUnmatched
          ? `רשומת המסמך **נוצרה** בפיירברי בלי שיוך. יש לפתוח את הקישור, לזהות את\n` +
            `הלקוחה, ולשייך את הרשומה ללקוחה ולתשלום.\n\n`
          : `לא נמצאה רשומת "תשלום" עם המזהה הזה. יש לפתוח את הקישור, לזהות את הלקוחה,\n` +
            `וליצור/לשייך ידנית רשומת מסמך.\n\n`) +
        `שים לב: בזיכוי גרואו פותחת עסקה **חדשה** עם מזהה חדש, שאינו קשור לעסקה\n` +
        `המקורית. לכן שיוך אוטומטי בלתי אפשרי כל עוד identifyParam ריק.\n\n` +
        `ריצת n8n: ${ev.executionUrl}`);
      warnings.push(docRefUnmatched
        ? 'לא נמצאה רשומת תשלום עם מזהה העסקה — המסמך נוצר בלי שיוך ונפתחה משימה.'
        : 'לא נמצאה רשומת תשלום עם מזהה העסקה שהתקבל בחשבונית — נפתחה משימה.');
      return [{ json: { ...ev, branch: 'INVOICE_NO_MATCH', ops, warnings, decisions,
        docTypeResolved: docTypeEarly,
        docRefNumber: S(ev.docRefNumber), docPhone: S(ev.docPhone),
        matchedFromDocument: matchedSomething,
        summary: !docRefUnmatched
          ? 'לא נמצא תשלום מתאים לחשבונית — נפתחה משימה לטיפול ידני.'
          : (matchedSomething
             ? `${docTypeEarly} ${ev.invoiceNumber} נשמר ושויך לפי המזהים שבמסמך.`
             : `${docTypeEarly} ${ev.invoiceNumber} נשמר בפיירברי בלי שיוך — נפתחה משימה לשיוך ידני.`),
        accountid, accountName: custLabel, accountEmail, saleid, productName, productId, ownerid } }];
    }
    const paymentId = S(txPayment.customobject1039id);
    // תיעוד התשלום המתאים: העדכני ביותר שנפרע בהצלחה תחת אותו תשלום; אחרת האחרון.
    const linked = docs.filter((x) => S(x.pcfPaymentCollection) === paymentId);
    const paidDocs = linked.filter((x) => pickNum(x.pcfPaymetStatus, DS_LABELS) === 1)
      .sort((a, b) => String(b.createdon || '').localeCompare(String(a.createdon || '')));
    const docRec = paidDocs[0] || linked[linked.length - 1] || null;
    if (!docRec) warnings.push('נמצא תשלום אך לא נמצא תיעוד תשלום מקושר — המסמך ייווצר בלי שיוך לתיעוד.');

