      pcfDocumentType: cut(docType, 190),
      pcfLinkToDocument: S(ev.invoiceUrl),
      pcfCreatedByPersonOrSystem: 2,
      pcfExternalSoftwareID1: ev.idemKeyBase,
      pcfExternalSoftwareID2: 'GROW',
    };
    lookupOrOmit(body, 'pcfaccountid', accountid);
    lookupOrOmit(body, 'pcfLinkedSale', saleid);
    lookupOrOmit(body, 'pcfPaymentCollection', paymentId);
    if (docRec) lookupOrOmit(body, 'pcfPaymentRecord', S(docRec.customobject1018id));
