    // השלמת "מספר מסמך" על תיעוד התשלום
    if (docRec) {
      add({ ref: 'docNumber', kind: 'update', object: '1018',
        recordId: S(docRec.customobject1018id), label: 'עדכון מספר מסמך בתיעוד התשלום',
        body: { pcfInvoiceNumber1: S(ev.invoiceNumber) } });
    }

    decisions.push('ענף E — מסמך חשבונאי');
    return [{ json: { ...ev, branch: 'INVOICE', ops, warnings, decisions,
      summary: 'נוצרה רשומת מסמך ושויכה לתשלום ולתיעוד התשלום.',
      accountid, accountName: custLabel, accountEmail, saleid, productName, productId, ownerid } }];
  }

  // ============================ לא מזוהה ============================
  taskOp('taskUnknown', 'וובהוק מגרואו שלא זוהה — נדרשת בדיקה',
    `התקבל וובהוק מגרואו שלא תואם לאף אחד מהפורמטים המוכרים.\n` +
    `payload:\n${JSON.stringify(ev._raw).slice(0, 3000)}\nריצה: ${ev.executionUrl}`);
  warnings.push('סוג הוובהוק לא זוהה — נפתחה משימת בדיקה עם ה-payload הגולמי.');
  return [{ json: { ...ev, branch: 'UNKNOWN', ops, warnings, decisions,
    summary: 'סוג הוובהוק לא זוהה. נפתחה משימה עם ה-payload המלא כדי שנוכל להשלים את הענף.',
    accountid, accountName: custLabel, accountEmail, saleid, productName, productId, ownerid } }];
}


// ── הכרעת מצב ההרצה ──────────────────────────────────────────────────────
// DRY_RUN גלובלי נשאר true, אבל חשבון שמופיע ברשימת הבדיקה המורשית רץ מלא.
// ההכרעה נעשית כאן ולא בצומת הנירמול, כי לוובהוק החשבונית אין טלפון —
// הזיהוי שלו אפשרי רק אחרי שנמצאה רשומת התשלום ומתוכה הלקוחה.
function LOGIC(ctx) {
  const out = PLAN_CORE(ctx);
  const ev = ctx.ev;
  const cfg = ev._cfg || {};
  const j = out[0].json;
  const up = (x) => String(x || '').toUpperCase();
  const phones = cfg.LIVE_TEST_PHONES || [];
  const accts = (cfg.LIVE_TEST_ACCOUNT_IDS || []).map(up);
  const names = (cfg.LIVE_TEST_ACCOUNT_NAMES || []).map((x) => String(x || '').trim());
  let live = (ev.phone && phones.indexOf(ev.phone) !== -1)
          || (j.accountid && accts.indexOf(up(j.accountid)) !== -1)
          // 🔴 התאמה לפי שם הלקוחה — שורדת מחיקה ויצירה מחדש של הרשומה,
          //    ולכן היא הרשת שתופסת את וובהוק החשבונית שאין בו טלפון.
          || (j.accountName && names.indexOf(String(j.accountName).trim()) !== -1);
  // חשבונית יתומה — נפתחת משימה בפועל כדי שהמסמך לא ייעלם בשקט
  if (!live && cfg.ALWAYS_LIVE_UNMATCHED_INVOICE && j.branch === 'INVOICE_NO_MATCH') {
    live = true;
    j.decisions.push('חשבונית שלא שויכה — נפתחת משימה בפועל (משימה בלבד, ללא רשומה כספית).');
  }

  j.liveTest = !!live;
  j.DRY_RUN = cfg.DRY_RUN && !live;
  j.decisions = j.decisions || [];
  if (live) {
    j.decisions.push('🔴 חשבון בדיקה מורשה — הריצה מתבצעת בפועל והרשומות ייווצרו בפיירברי.');
  } else if (cfg.DRY_RUN) {
    j.decisions.push('DRY_RUN — הלקוחה אינה ברשימת הבדיקה המורשית, לא נכתבה שום רשומה.');
  }
  return out;
}

