// WF-20 · צומת 9 — פירוק תוכנית הפעולה לשלושה גלי ביצוע
// ============================================================================
// גל 1: רשומת האב (התשלום) — כולם מפנים אליה.
// גל 2: כל מה שמפנה לאב או לא מפנה לכלום (תיעודי תשלום, מסמך, משימה, הערות).
// גל 3: כל מה שמפנה לרשומה שנוצרה בגל 2 (הערות על תיעודי תשלום).
// אין לולאה — שלושה שלבים ליניאריים מספיקים לכל הענפים.
// ============================================================================

// ==== LOGIC (pure) ====
function LOGIC(ctx) {
  const plan = ctx.plan;
  const base = plan._cfg.FIREBERRY_BASE;
  const ops = Array.isArray(plan.ops) ? plan.ops : [];

  const NOOP = {
    _noop: true,
    method: 'POST',
    url: `${base}/api/v3/query`,
    body: { objectType: 1039, fields: [{ name: 'customobject1039id' }], pageSize: 1, pageNumber: 1 },
    label: 'ללא פעולת אב — קריאת קריאה-בלבד לשמירת רציפות',
    ref: '_noop',
  };

  // 🔒 מנעול בטיחות שני: תוכנית שאינה מסומנת לכתיבה לא מייצרת שום קריאת כתיבה.
  if (plan.DRY_RUN !== false) {
    return [{ json: Object.assign({}, NOOP, { _childOps: [], _wave3Ops: [], _blocked: true,
      label: '🔒 נחסם — התוכנית אינה מסומנת לכתיבה בפועל' }) }];
  }

  const refsIn = (op) => {
    const out = [];
    const walk = (v) => {
      if (typeof v === 'string' && v.charAt(0) === '@') out.push(v.slice(1));
      else if (Array.isArray(v)) v.forEach(walk);
      else if (v && typeof v === 'object') Object.keys(v).forEach((k) => walk(v[k]));
    };
    walk(op.body);
    // הפניה במזהה הרשומה של פעולת עדכון (למשל: עדכון שדה ברשומת האב שנוצרה זה עתה)
    if (op.recordIdRef) out.push(String(op.recordIdRef).replace(/^@/, ''));
    return out;
  };

  const referenced = new Set();
  ops.forEach((o) => refsIn(o).forEach((r) => referenced.add(r)));

  const parentOp = ops.find((o) => referenced.has(o.ref)) || null;
  const parentRef = parentOp ? parentOp.ref : null;

  const rest = ops.filter((o) => !parentRef || o.ref !== parentRef);
  const wave2 = rest.filter((o) => refsIn(o).every((r) => r === parentRef));
  const wave3 = rest.filter((o) => refsIn(o).some((r) => r !== parentRef));

  function toRequest(op) {
    // פעולת אב לעולם אינה תלויה בהפניה, ולכן recordIdRef אינו רלוונטי כאן.
    const url = op.kind === 'update'
      ? `${base}/api/record/${op.object}/${op.recordId}`
      : `${base}/api/record/${op.object}`;
    return {
      _noop: false, ref: op.ref, label: op.label, object: op.object,
      kind: op.kind, recordId: op.recordId || '',
      method: op.kind === 'update' ? 'PUT' : 'POST',
      url, body: op.body,
    };
  }

  const parentReq = parentOp ? toRequest(parentOp) : NOOP;

  return [{
    json: Object.assign({}, parentReq, {
      _childOps: wave2,
      _wave3Ops: wave3,
      _planRef: { branch: plan.branch, summary: plan.summary },
    }),
  }];
}

// ==== N8N BINDING ====
return LOGIC({ plan: $('בניית תוכנית פעולה').first().json });

// ============================================================================
// WF-20 · צומת 11 — חילוץ מזהה רשומת האב ובניית פעולות גל 2
// ============================================================================
// מבנה התשובה של POST /api/record/{objectType} אינו מתועד באופן יציב —
// לכן חילוץ המזהה עובר כמה נתיבים אפשריים, ובנפילה מוחלטת ההפניה מושמטת
// והרשומה התלויה לא נוצרת יתומה.
// ============================================================================

// ==== LOGIC (pure) ====
// 🔴 14/09/2026 — לא לכל אובייקט בפיירברי המזהה נקרא customobject{N}id.
// לאובייקטי הליבה יש שם משלהם. חוסר המיפוי הזה גרם לכך שיצירת **תהליך
// מכירה** כרשומת אב "הצליחה" אבל המזהה לא חולץ: הרשומות התלויות נוצרו
// בלי שיוך, תיעוד התשלום לא נוצר כלל, והתהליך המקצועי לא הופעל.
const ID_FIELD_BY_OBJECT = {
  '1': 'accountid', '2': 'contactid', '4': 'opportunityid', '6': 'activityid',
  '9': 'systemuserid', '10': 'taskid', '13': 'salesorderid', '14': 'productid',
  'note': 'noteid',
};
function idKeysFor(object) {
  const o = String(object);
  const keys = [];
  if (ID_FIELD_BY_OBJECT[o]) keys.push(ID_FIELD_BY_OBJECT[o]);
  keys.push('customobject' + o + 'id');
  return keys;
}

function extractRecordId(resp, object) {
  if (!resp || typeof resp !== 'object') return '';
  const keys = idKeysFor(object);
  const cands = [];
  for (let i = 0; i < keys.length; i++) {
    const k = keys[i];
    cands.push(
      resp[k],
      resp.data && resp.data[k],
      resp.Record && resp.Record[k],
      resp.data && resp.data.Record && resp.data.Record[k],
      resp.data && resp.data.Data && resp.data.Data[0] && resp.data.Data[0][k]
    );
  }
  cands.push(
    resp.id, resp._id, resp.noteid,
    resp.data && resp.data.id, resp.data && resp.data._id,
    resp.data && resp.data.Record && resp.data.Record.noteid
  );
  for (const c of cands) {
    const v = (c === undefined || c === null) ? '' : String(c).trim();
    if (v && /^[0-9a-fA-F-]{30,}$/.test(v)) return v;
  }
  return '';
}

function resolveRefs(value, refs) {
  if (typeof value === 'string' && value.charAt(0) === '@') {
    const key = value.slice(1);
    return refs[key] !== undefined ? refs[key] : '';
  }
  if (Array.isArray(value)) return value.map((v) => resolveRefs(v, refs));
  if (value && typeof value === 'object') {
    const out = {};
    for (const k of Object.keys(value)) {
      const rv = resolveRefs(value[k], refs);
      // לא כותבים הפניה ריקה — פיירברי מחזיר 403 על שדה מזהה שאינו GUID
      if (rv === '' && typeof value[k] === 'string' && value[k].charAt(0) === '@') continue;
      out[k] = rv;
    }
    return out;
  }
  return value;
}

function buildRequest(op, refs, base) {
  // 🔴 פעולת עדכון יכולה לכוון לרשומה שנוצרה בגל קודם (recordIdRef).
  //    אם ההפניה לא נפתרה — אסור לשלוח PUT לכתובת בלי מזהה; הפעולה מושתקת.
  const rid = op.recordIdRef ? String(refs[String(op.recordIdRef).replace(/^@/, '')] || '') : String(op.recordId || '');
  if (op.kind === 'update' && !rid) {
    return {
      _noop: true, ref: op.ref, label: `${op.label} — דולג (מזהה הרשומה לא נפתר)`,
      object: op.object, kind: op.kind, recordId: '',
      method: 'POST', url: `${base}/api/v3/query`,
      body: { objectType: 1039, fields: [{ name: 'customobject1039id' }], pageSize: 1, pageNumber: 1 },
    };
  }
  const url = op.kind === 'update'
    ? `${base}/api/record/${op.object}/${rid}`
    : `${base}/api/record/${op.object}`;
  return {
    _noop: false, ref: op.ref, label: op.label, object: op.object,
    kind: op.kind, recordId: rid,
    method: op.kind === 'update' ? 'PUT' : 'POST',
    url, body: resolveRefs(op.body, refs),
  };
}

function LOGIC(ctx) {
  const parent = ctx.parent;
  const createResp = ctx.createResp;
  const plan = ctx.plan;
  const base = plan._cfg.FIREBERRY_BASE;

  const NOOP = {
    _noop: true, ref: '_noop', label: 'אין פעולות בגל זה',
    method: 'POST', url: `${base}/api/v3/query`,
    body: { objectType: 1039, fields: [{ name: 'customobject1039id' }], pageSize: 1, pageNumber: 1 },
  };

  if (parent._blocked || plan.DRY_RUN !== false) {
    return [{ json: Object.assign({}, NOOP, { _blocked: true, _wave3Ops: [],
      label: '🔒 נחסם — התוכנית אינה מסומנת לכתיבה בפועל' }) }];
  }

  let parentId = parent._noop ? '' : extractRecordId(createResp, parent.object);
  let parentRecovered = false;

  // 🔴 ממצא 19/08 — פיירברי עלול להחזיר HTTP 400 ולכתוב את הרשומה בכל זאת.
  // לכן כשחילוץ המזהה נכשל, בודקים בשאילתת האימות אם הרשומה בכל זאת נוצרה.
  if (!parent._noop && !parentId) {
    if (parent.kind === 'update' && parent.recordId) {
      parentId = String(parent.recordId);
    } else {
      const rows = (ctx.verifyResp && Array.isArray(ctx.verifyResp.data)) ? ctx.verifyResp.data : [];
      const key = `customobject${parent.object}id`;
      const hit = rows.find((r) => r && r[key]);
      if (hit) { parentId = String(hit[key]); parentRecovered = true; }
    }
  }

  const parentFailed = !parent._noop && !parentId;
  const refs = {};
  if (parent.ref) refs[parent.ref] = parentId;

  const childOps = Array.isArray(parent._childOps) ? parent._childOps : [];
  const wave3 = Array.isArray(parent._wave3Ops) ? parent._wave3Ops : [];
  const extra = { _parentId: parentId, _parentFailed: parentFailed, _parentRecovered: parentRecovered, _wave3Ops: wave3 };

  if (childOps.length === 0) return [{ json: Object.assign({}, NOOP, extra) }];
  return childOps.map((op) => ({ json: Object.assign(buildRequest(op, refs, base), extra) }));
}

// ==== N8N BINDING ====
return LOGIC({
  parent: $('הפרדת פעולת האב').first().json,
  createResp: $('יצירת רשומת האב בפיירברי').first().json,
  verifyResp: $input.first().json,
  plan: $('בניית תוכנית פעולה').first().json,
});

// ============================================================================
// WF-20 · צומת 13 — בניית פעולות גל 3
// ============================================================================
// פעולות שתלויות ברשומות שנוצרו בגל 2 (הערות על תיעודי תשלום).
// ההצמדה בין בקשה לתשובה נעשית לפי סדר הפריטים — צומת ה-HTTP של n8n
// מחזיר פריט אחד לכל פריט נכנס, באותו סדר.
// ============================================================================

// ==== LOGIC (pure) ====
// 🔴 14/09/2026 — לא לכל אובייקט בפיירברי המזהה נקרא customobject{N}id.
// לאובייקטי הליבה יש שם משלהם. חוסר המיפוי הזה גרם לכך שיצירת **תהליך
// מכירה** כרשומת אב "הצליחה" אבל המזהה לא חולץ: הרשומות התלויות נוצרו
// בלי שיוך, תיעוד התשלום לא נוצר כלל, והתהליך המקצועי לא הופעל.
const ID_FIELD_BY_OBJECT = {
  '1': 'accountid', '2': 'contactid', '4': 'opportunityid', '6': 'activityid',
  '9': 'systemuserid', '10': 'taskid', '13': 'salesorderid', '14': 'productid',
  'note': 'noteid',
};
function idKeysFor(object) {
  const o = String(object);
  const keys = [];
  if (ID_FIELD_BY_OBJECT[o]) keys.push(ID_FIELD_BY_OBJECT[o]);
  keys.push('customobject' + o + 'id');
  return keys;
}

function extractRecordId(resp, object) {
  if (!resp || typeof resp !== 'object') return '';
  const keys = idKeysFor(object);
  const cands = [];
  for (let i = 0; i < keys.length; i++) {
    const k = keys[i];
    cands.push(
      resp[k],
      resp.data && resp.data[k],
      resp.Record && resp.Record[k],
      resp.data && resp.data.Record && resp.data.Record[k],
      resp.data && resp.data.Data && resp.data.Data[0] && resp.data.Data[0][k]
    );
  }
  cands.push(
    resp.id, resp._id, resp.noteid,
    resp.data && resp.data.id, resp.data && resp.data._id,
    resp.data && resp.data.Record && resp.data.Record.noteid
  );
  for (const c of cands) {
    const v = (c === undefined || c === null) ? '' : String(c).trim();
    if (v && /^[0-9a-fA-F-]{30,}$/.test(v)) return v;
  }
  return '';
}

function resolveRefs(value, refs) {
  if (typeof value === 'string' && value.charAt(0) === '@') {
    const key = value.slice(1);
    return refs[key] !== undefined ? refs[key] : '';
  }
  if (Array.isArray(value)) return value.map((v) => resolveRefs(v, refs));
  if (value && typeof value === 'object') {
    const out = {};
    for (const k of Object.keys(value)) {
      const rv = resolveRefs(value[k], refs);
      if (rv === '' && typeof value[k] === 'string' && value[k].charAt(0) === '@') continue;
      out[k] = rv;
    }
    return out;
  }
  return value;
}

function LOGIC(ctx) {
  const plan = ctx.plan;
  const base = plan._cfg.FIREBERRY_BASE;
  const reqs = ctx.childReqs || [];
  const resps = ctx.childResps || [];

  const NOOP = {
    _noop: true, ref: '_noop', label: 'אין פעולות בגל 3',
    method: 'POST', url: `${base}/api/v3/query`,
    body: { objectType: 1039, fields: [{ name: 'customobject1039id' }], pageSize: 1, pageNumber: 1 },
  };

  if (plan.DRY_RUN !== false) return [{ json: Object.assign({}, NOOP, { _blocked: true }) }];

  const refs = {};
  reqs.forEach((r, i) => {
    if (!r || r._noop || !r.ref) return;
    refs[r.ref] = r.kind === 'update' ? r.recordId : extractRecordId(resps[i], r.object);
  });
  // ההפניה לרשומת האב עדיין נחוצה גם בגל 3
  const parentId = (reqs[0] && reqs[0]._parentId) || '';
  const parentRef = ctx.parentRef;
  if (parentRef && parentId) refs[parentRef] = parentId;

  const ops = (reqs[0] && reqs[0]._wave3Ops) || [];
  if (!ops.length) return [{ json: NOOP }];

  return ops.map((op) => {
    const rid = op.recordIdRef
      ? String(refs[String(op.recordIdRef).replace(/^@/, '')] || '')
      : String(op.recordId || '');
    const url = op.kind === 'update'
      ? `${base}/api/record/${op.object}/${rid}`
      : `${base}/api/record/${op.object}`;
    const body = resolveRefs(op.body, refs);
    // 🔴 14/09/2026 — הבדיקה `!body.objectid` נכונה **רק להערה**: הערה בלי
    //    רשומת יעד היא חסרת ערך. אבל היא הוחלה על *כל* יצירה בגל 3, ולכן
    //    "תיעוד תשלום" (1018) — שאין לו objectid כלל, הקישורים שלו הם
    //    pcfPaymentCollection/pcfSale — דולג **תמיד** כשהוא נפל לגל 3.
    //    זה קרה בכל רכישה שבה רשומת האב היא תהליך מכירה חדש: התשלום נרשם,
    //    אבל תיעוד התשלום לא נוצר בכלל. אם קישור לא נפתר — הרשומה נוצרת
    //    בכל זאת (עדיף רשומה לא משויכת על פני כסף שלא נרשם).
    const needsObjectId = String(op.object) === 'note';
    const missing = op.kind === 'update' ? !rid : (needsObjectId && !body.objectid);
    return { json: {
      _noop: !!missing, ref: op.ref, label: op.label + (missing ? ' (דולג — לא נמצא מזהה יעד)' : ''),
      object: op.object, kind: op.kind, recordId: rid,
      method: missing ? 'POST' : (op.kind === 'update' ? 'PUT' : 'POST'),
      url: missing ? NOOP.url : url,
      body: missing ? NOOP.body : body,
    } };
  });
}

// ==== N8N BINDING ====
return LOGIC({
  plan: $('בניית תוכנית פעולה').first().json,
  parentRef: $('הפרדת פעולת האב').first().json.ref,
  childReqs: $('בניית פעולות הבנים').all().map((i) => i.json),
  childResps: $input.all().map((i) => i.json),
});

// ============================================================================
// WF-20 · צומת 15 — סיכום הריצה (שלושת הגלים)
// ============================================================================

// ==== LOGIC (pure) ====
// 🔴 14/09/2026 — לא לכל אובייקט בפיירברי המזהה נקרא customobject{N}id.
// לאובייקטי הליבה יש שם משלהם. חוסר המיפוי הזה גרם לכך שיצירת **תהליך
// מכירה** כרשומת אב "הצליחה" אבל המזהה לא חולץ: הרשומות התלויות נוצרו
// בלי שיוך, תיעוד התשלום לא נוצר כלל, והתהליך המקצועי לא הופעל.
const ID_FIELD_BY_OBJECT = {
  '1': 'accountid', '2': 'contactid', '4': 'opportunityid', '6': 'activityid',
  '9': 'systemuserid', '10': 'taskid', '13': 'salesorderid', '14': 'productid',
  'note': 'noteid',
};
function idKeysFor(object) {
  const o = String(object);
  const keys = [];
  if (ID_FIELD_BY_OBJECT[o]) keys.push(ID_FIELD_BY_OBJECT[o]);
  keys.push('customobject' + o + 'id');
  return keys;
}

function extractRecordId(resp, object) {
  if (!resp || typeof resp !== 'object') return '';
  const keys = idKeysFor(object);
  const cands = [];
  for (let i = 0; i < keys.length; i++) {
    const k = keys[i];
    cands.push(
      resp[k],
      resp.data && resp.data[k],
      resp.Record && resp.Record[k],
      resp.data && resp.data.Record && resp.data.Record[k],
      resp.data && resp.data.Data && resp.data.Data[0] && resp.data.Data[0][k]
    );
  }
  cands.push(
    resp.id, resp._id, resp.noteid,
    resp.data && resp.data.id, resp.data && resp.data._id,
    resp.data && resp.data.Record && resp.data.Record.noteid
  );
  for (const c of cands) {
    const v = (c === undefined || c === null) ? '' : String(c).trim();
    if (v && /^[0-9a-fA-F-]{30,}$/.test(v)) return v;
  }
  return '';
}

function LOGIC(ctx) {
  const plan = ctx.plan;
  const parent = ctx.parent;

  const looksLikeError = (r) => {
    if (!r || typeof r !== 'object') return true;
    if (r.success === false) return true;
    if (r.Message || r.message) return true;
    if (r.error) return true;
    return false;
  };

  const results = [];
  if (!parent._noop && !parent._blocked) {
    results.push({
      wave: 1, ref: parent.ref, label: parent.label, object: parent.object, kind: parent.kind,
      // 🔴 אם הרשומה שוחזרה בשאילתת האימות — הפעולה הצליחה בפועל אף שקוד התשובה היה שגיאה.
      ok: ctx.parentRecovered ? true : !looksLikeError(ctx.parentResp),
      recovered: !!ctx.parentRecovered,
      recordId: ctx.parentId || '', response: ctx.parentResp,
    });
  }
  const pair = (reqs, resps, wave) => {
    (reqs || []).forEach((req, i) => {
      if (!req || req._noop || req._blocked) return;
      results.push({
        wave, ref: req.ref, label: req.label, object: req.object, kind: req.kind,
        ok: !looksLikeError(resps[i]), recordId: req.recordId || '', response: resps[i],
      });
    });
  };
  pair(ctx.childReqs, ctx.childResps, 2);
  pair(ctx.wave3Reqs, ctx.wave3Resps, 3);

  const failed = results.filter((r) => !r.ok);
  const parentFailed = (ctx.childReqs || []).some((r) => r && r._parentFailed);

  // ---------- תיקון שורש 14/09/2026 — פתרון @ref לפני החזרה החוצה ----------
  // 🔴 plan.accountid/plan.saleid יכולים להיות מחרוזת-הפניה גולמית ("@newAccount")
  // כשהחשבון/העסקה נוצרו רק בריצה הזו (למשל תיקון "לקוחה חדשה" 14/09). מפת
  // ה-refs שנבנתה בתוך צמתי הגלים היא ארעית ולא זמינה כאן — לכן בונים אותה
  // מחדש מהתוצאות שכבר נאספו למעלה (results), בדיוק כמו ב"בניית פעולות גל 3".
  const refsMap = {};
  if (parent.ref) refsMap[parent.ref] = ctx.parentId || '';
  (ctx.childReqs || []).forEach((r, i) => {
    if (!r || r._noop || !r.ref) return;
    refsMap[r.ref] = r.kind === 'update' ? (r.recordId || '') : extractRecordId((ctx.childResps || [])[i], r.object);
  });
  (ctx.wave3Reqs || []).forEach((r, i) => {
    if (!r || r._noop || !r.ref) return;
    refsMap[r.ref] = r.kind === 'update' ? (r.recordId || '') : extractRecordId((ctx.wave3Resps || [])[i], r.object);
  });
  const resolveMaybeRef = (val) => {
    if (typeof val === 'string' && val.charAt(0) === '@') {
      const key = val.slice(1);
      return refsMap[key] !== undefined ? refsMap[key] : '';
    }
    return val;
  };
  const resolvedAccountId = resolveMaybeRef(plan.accountid);
  const resolvedSaleId = resolveMaybeRef(plan.saleid);
  // ---------------------------------------------------------------------

  return [{
    json: {
      success: failed.length === 0 && !parentFailed,
      dryRun: false,
      liveTest: plan.liveTest,
      branch: plan.branch,
      summary: plan.summary,
      decisions: plan.decisions,
      warnings: plan.warnings,
      eventType: plan.eventType,
      routing: { webhookKey: plan.webhookKey, matched: plan.webhookKeyLabel, classifiedBy: plan.classifiedBy },
      account: { id: resolvedAccountId, name: plan.accountName },
      saleid: resolvedSaleId,
      product: plan.productName,
      coupon: plan.couponDiscount > 0
        ? { code: plan.couponCode, discount: plan.couponDiscount, source: plan.couponSource, listPrice: plan.listedTotal }
        : null,
      transactionId: plan.transactionId,
      asmachta: plan.asmachta,
      operations: results,
      failedCount: failed.length,
      parentIdMissing: !!parentFailed,
      parentRecovered: !!ctx.parentRecovered,
      nextWorkflowUrl: plan.nextWorkflowUrl || '',
      executionUrl: plan.executionUrl,
    },
  }];
}

// ==== N8N BINDING ====
return LOGIC({
  plan: $('בניית תוכנית פעולה').first().json,
  parent: $('הפרדת פעולת האב').first().json,
  parentResp: $('יצירת רשומת האב בפיירברי').first().json,
  parentId: ($('בניית פעולות הבנים').first().json || {})._parentId || '',
  parentRecovered: !!($('בניית פעולות הבנים').first().json || {})._parentRecovered,
  childReqs: $('בניית פעולות הבנים').all().map((i) => i.json),
  childResps: $('ביצוע פעולות בפיירברי').all().map((i) => i.json),
  wave3Reqs: $('בניית פעולות גל 3').all().map((i) => i.json),
  wave3Resps: $input.all().map((i) => i.json),
});

// ============================================================================
// WF-20 · צומת 17 — הפעלת התהליך המקצועי (WF-22) בסיום תשלום מוצלח
// ============================================================================
// ההפרדה מכוונת: התשלום והצד המקצועי הם שני תהליכים נפרדים לגמרי, שמדברים
// דרך וובהוק. כך אפשר יהיה בעתיד להפעיל את הצד המקצועי מטריגר אחר לגמרי.
//
// נורה רק על **רכישה חדשה** ועל **הקמת הוראת קבע** — לא על חיובי המשך,
// לא על מסמכים חשבונאיים ולא על מסירות חוזרות.
//
// 🔴 תיקון שורש 14/09/2026: accountid/saleid נקראים מ-sum (הפלט המפוענח של
// "סיכום הריצה") ולא מ-plan הגולמי. plan.accountid/plan.saleid יכולים להיות
// מחרוזת-הפניה ("@newAccount"/"@newSale") כשהחשבון/העסקה נוצרו רק בריצה הזו
// (למשל לקוחה חדשה לגמרי) — "סיכום הריצה" כבר פותר את זה למזהה אמיתי לפני
// שהוא מגיע לכאן. שימוש ב-plan הגולמי כאן היה שולח "@newAccount" מילולית
// ל-WF-22, ומפיל בשקט את כל שרשרת התהליך המקצועי (קלאודצ'אט/וואטסאפ/ליווי).
// ============================================================================

// ==== LOGIC (pure) ====
const PRO_BRANCHES = ['NEW_PURCHASE', 'STANDING_ORDER_SETUP', 'STANDING_ORDER_BACKOFFICE'];

function LOGIC(ctx) {
  const plan = ctx.plan;
  const sum = ctx.summary || {};
  const cfg = plan._cfg;
  const url = String(cfg.PRODUCT_SETUP_WEBHOOK_URL || '').trim();
  const IDLE = `${cfg.FIREBERRY_BASE}/api/v3/query`;
  const idleBody = { objectType: 1039, fields: [{ name: 'customobject1039id' }], pageSize: 1, pageNumber: 1 };

  const skip = (why) => [{ json: Object.assign({}, sum, {
    proHook: { fired: false, reason: why }, proUrl: IDLE, proBody: idleBody,
  }) }];

  const accountId = (sum.account && sum.account.id) || '';
  const saleId = sum.saleid || '';

  if (!url) return skip('לא הוגדרה כתובת לתהליך המקצועי (PRODUCT_SETUP_WEBHOOK_URL ריק)');
  if (plan.DRY_RUN !== false) return skip('DRY_RUN — התהליך המקצועי לא הופעל');
  if (PRO_BRANCHES.indexOf(plan.branch) === -1) return skip(`ענף ${plan.branch} אינו רכישה חדשה`);
  if (sum.success === false) return skip('התשלום לא נקלט במלואו — התהליך המקצועי לא הופעל');
  if (!accountId) return skip('אין לקוחה משויכת');

  return [{ json: Object.assign({}, sum, {
    proHook: { fired: true, reason: '' },
    proUrl: url,
    proBody: {
      accountid: accountId,
      accountName: plan.accountName,
      phone: plan.phone,
      email: plan.accountEmail || '',
      saleid: saleId,
      productId: plan.productId,
      productName: plan.productName,
      grossTotal: plan.grossTotal,
      asmachta: plan.asmachta,
      transactionId: plan.transactionId,
      purchaseDate: plan.paymentDateISO,
      paymentBranch: plan.branch,
      executionUrl: plan.executionUrl,
    },
  }) }];
}

// ==== N8N BINDING ====
return LOGIC({
  plan: $('בניית תוכנית פעולה').first().json,
  summary: $input.first().json,
});
